INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-01-006-0', 't-mm-01-006', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-01-006" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[833]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>6</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>. </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>MENOPAUSE AND </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>MANAGEMENT</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>:</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><em><strong> </strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[834]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Average age 50.5years 1 year earlier in smokers</strong></em></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[835]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Perimenopause:</strong></em></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[836]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Interval leading to menopause, an</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ovulatory cycle</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[837]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Climacteric:</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> period between Reproductive to non-reproductive life.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[838]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>              </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>It includes Menopause.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[839]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>POF:</strong></em></u></span><span class="mm-run" style=''color: ##FF0000; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''color: ##FF0000; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&lt; 40years</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[840]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> turner syndrome, Fragile X, Autoimmune Disorders, idiopathic.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[841]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1% of women experience POF</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[842]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Early menopause</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &lt; 45</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> years </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>between age of 40 – 45 yrs.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[843]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>E and P =&gt;    </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FSH </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pulsatility</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[844]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>E and P =&gt; </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Menopausal symptoms more in 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> year.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[845]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>After 1-year</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> estrogen </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>production</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> starts</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> from non-ovarian</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> source leading to reduced symptoms.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[846]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>    </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Menopause: </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[847]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>When women </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>have</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> no periods for one ear or more between 45 – 55 years.</span></p>
