INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-01-008-0', 't-mm-01-008', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-01-008" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1019]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>8</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>. HRT AFTER GYNAECOLOGICAL MALIGNANCY:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1020]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Ovarian Cancer:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1021]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>(Avoid)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1022]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Endometrial Cancer:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1023]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Type 1: Stage 1 and 2 </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1024]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>      </span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> E only if no chance of</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> malignant</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> foc</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>us</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1025]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Type 1: Stage 3 and 4 avoid.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1026]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Type 2: Avoid.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1027]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>C</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>ervical</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> Cancer</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>: </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1028]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>squ</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>amous</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> cell ca</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>rcinoma</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1029]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>stage 1 and 2</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1030]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>C</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ontinuous combined therapy (CCT) or</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Estrogen </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>(a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ccording</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>status of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>uterus)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1031]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>stage 3 &amp; 4 – Avoid.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1032]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Adenocarcinoma (avoid)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1033]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Vaginal + vulval Cancer: </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1034]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Seq cell = Estrogen or CCT.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1035]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>non seq – avoid</span></p>
