INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-01-009-0', 't-mm-01-009', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-01-009" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1040]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>9. </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>UNSHEDULED BLEEDING ON HRT</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1041]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>During </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3 months its common but report if persists after 3 months and workup.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1042]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Detailed history and examination, determine HRT given and duration.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1043]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1044]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1045]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Check </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Duration</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>&lt;6months</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>     </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>2. </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>&gt;</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> 6months</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>reassure </strong></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>      TVS</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Treatment:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Low dose E</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>    Dose or Change P.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Other options:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Stop HRT</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mirena.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Offer endometrial ablation or TAH in refractory cases.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>SCT</strong></u></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>CCT</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1046]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Determine</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1047]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1048]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Heavy prolonged</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Break Through</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> BLEEDING</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1049]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>withdrawal </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1050]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>1. </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>ET &gt;</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> 7mm</strong></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>2. ET &lt; 7mm</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- Endometrial</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>     - Observe</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>biopsy.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ple/ Hystro</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1051]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>ET &lt; 5mm</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>- atrophic endometrium</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>TVS check ET</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><u>&gt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> 5mm</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>- Biopsy </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1052]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1053]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1054]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1055]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Treatment:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1056]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Prolonged</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/ Heavy withdrawal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1057]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Change </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or    dose of P.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1058]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>    Dose of E.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1059]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bleeding in early </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>progesterone phase</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1060]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>  Dose or change type of P.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1061]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bl</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>eeding/ Spotting during E Phase</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1062]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><strong>TVS </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><strong>Criteria:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Any bleeding after 6 months.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Bleeding after </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>amenorrhea</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> on CCT</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Bleeding within 6 months in high risk.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><strong>Hysteroscopy Criteria:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Multiple episodes.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Focal lesion on TVS.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>ET </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><u>&gt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> 5mm on CCT, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><u>&gt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> 7mm on SCT.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Incomplete visualization of Endometrium on TVS.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>High risk group for Hyperplasia or CA.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>    E dose.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1063]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Irregular</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> change regimen.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1064]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Or     dose of P.</span></p>
