INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-01-010-0', 't-mm-01-010', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-01-010" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1073]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>10</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>. POST</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong> </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>MENOPAUSAL</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong> </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>BLEEDING:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1074]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Incidence = 10%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1075]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><em><strong>Causes:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1076]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>90% benign</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1077]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>10% malignant </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1078]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Atrophic vaginitis/ Endometritis = 75%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1079]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>HRT = 20%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1080]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Polyps = 12%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1081]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Hyperplasia</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> = 10%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1082]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>CA = 10%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1083]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Prolapse</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1084]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Evaluation</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1085]"><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>Local examination</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1086]"><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''> TVS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1087]"><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>Endometrial Biopsy</span><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''> if</span><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''> ET &gt; 5mm</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1088]"><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>Hysteroscopy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1089]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><em><strong>Management:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1090]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Endometrial thickness</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>&lt; 5mm =&gt; Endometrial</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> atrophy</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> – No t/m required</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1091]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Atrophic vagina: local E &amp; vaginal moisturizers.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1092]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Polyps + Submucosal-Fibroids =&gt; Hysteroscopic resection and Biopsy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1093]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Hyperplasia – </span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Hysterectomy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1094]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Malignancy =&gt; refer to</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>oncologist.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1095]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Polyp</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1096]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>&gt;remove if symptomatic or more than 1cm</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1097]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1098]"> </p>', 0);

