INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-01-011-0', 't-mm-01-011', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-01-011" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1099]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Aptos", sans-serif; font-size: 16pt''><strong>1</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Aptos", sans-serif; font-size: 16pt''><strong>1</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Aptos", sans-serif; font-size: 16pt''><strong>. CHRONIC PELVIC PAIN:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1100]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Definition: </strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1101]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Constant pain in lower Abdomen or pelvis of @ least 6months duration not occurring exclusively with menstruation or intercourse and not related to pregnancy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1102]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1103]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Causes</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> and treatment</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>: </strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1104]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Cyclic pain: </strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1105]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Hormon</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>e</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> related</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1106]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> t/m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> is</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> OCPs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> for </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6 months before offe</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ring</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>laparoscopy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1107]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Pelvic congestion</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1108]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>t/m </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>is </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>progestogen, GnRH</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> analogue </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1109]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Endometriosis/Ad</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>n</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>o</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>m</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>yosis</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> - progesterone, GnRH analogues, Danazol, Mirena, COCP.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1110]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Adhesions</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1111]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fine Adhesions:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1112]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No role of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Adhesiolysis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1113]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dense</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Adhesions</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1114]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Adhesiolysis improve pain</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1115]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Trapped ovary </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>syndrome </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>suppression</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> with GnRH </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>  </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>analogues or </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oophorectomy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1116]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Residual ovary syndrome suppression with GnRH</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> analogues</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oophorectomy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1117]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><strong>IBS:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1118]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>50% of CPP t</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>/m Diet + Antispasmodics </span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Mebeverin</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> HCL.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1119]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><strong>interstitial cystitis:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1120]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>38 – 84%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1121]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><strong>Musculoskeletal:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1122]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Spas</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>m of </span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>pelvic floor </span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>muscles, Tender </span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>sacroiliac (SI) joint </span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>or </span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>pubic symphysis</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1123]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><strong>Nerve entrapment:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1124]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>3.7% after </span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>C/S, </span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Pfannenstiel</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> incision.</span></p>
