INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-01-019-0', 't-mm-01-019', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-01-019" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1469]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>1</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>8</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>. MRKH:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1470]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-46 XY</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1471]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>N</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ormal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> second</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ary</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> sexual characters. </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1472]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1 in 4000 – 5000.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1473]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Sporadic – Multifactorial inheritance</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1474]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Autosomal dominant</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1475]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Single gene defect HOX gene</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1476]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><em><strong>Classification:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1477]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><strong>Type </strong></span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><strong>I</strong></span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><strong>: (64%)</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1478]"><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>Typical, symmetrical </span><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>uterovaginal </span><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>aplasia/Hypoplasia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1479]"><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>Tubes + ovaries Normal, uterine buds Present</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1480]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><strong>Type II: (24%)</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1481]"><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>Atypical, Asymmetrical UV aplasia</span><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>/h</span><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>ypoplasia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1482]"><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>Tubal Hypo</span><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>plasia</span><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>/Aplasia one or both</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1483]"><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>Ovarian malformation one or both</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1484]"><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''><u>+</u></span><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''> Renal Anomalies</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1485]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><strong>Type III: 12% MURCS Syndrome: </strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1486]"><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>Mullerian aplasia </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1487]"><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>Renal </span><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>dysplasia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1488]"><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>Cervical somite anomalies =&gt; Skeletal system</span><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''> and cardiac </span><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>abnormality</span><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''>,</span><span class="mm-run" style=''color: ##2F5496; font-family: "Aptos", sans-serif; font-size: 12pt''> muscular Weakness.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1489]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><em><strong>Other organs involvement:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1490]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Renal 40% – 12% absent kidney</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1491]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Skeletal 12 – 20% </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1492]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Auditory 10 – 25% </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1493]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Cardiac Rarely</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1494]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Sensory neural deafness</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1495]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><em><strong>Clinical presentation:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1496]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>P</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>amenorrhea</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> 70 – 80% </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1497]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Cyclical abd pain – if functional endometrium in uterine </span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>bud</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>, needs to be removed</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1498]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Dyspareunia</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1499]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Subfertility</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1500]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><em><strong>On Examination:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1501]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>N</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>ormal</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> ssc</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1502]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Ovaries – present </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1503]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Uterus – absent</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1504]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Vagina – blind </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1505]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''><em><strong>Diagnostic tests:</strong></em></span></p>
