INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-01-021-0', 't-mm-01-021', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-01-021" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1592]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>20</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>. FEMALE GENITAL MUTILATION (FGM):</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1593]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>WHO FGM Classification:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1594]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Type I:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Partial/Total removal of clitor</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>is</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>prepuce, clitoridectomy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1595]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Type II:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Type </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> + removal of labia minor</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a with or without</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> labia Major</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> (excision).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1596]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Type III: </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>infibulation:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1597]"><span class="mm-run" style=''color: ##FF0000; font-family: "Calibri", sans-serif; font-size: 12pt''>- </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Narrowing of vaginal orifice with creation of a covering seal by cutting and </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>a positioning</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> the labia minora &amp;/or a major</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> with or without excision of clitoris. </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1598]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Type </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>I</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>V:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> All other harmful procedure to genital</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> for non-medical purposes like: pricing, pricking, incising, scraping &amp; cauterization.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1599]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Global Epidemiology:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1600]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>UNICEF: 125million all over the world.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1601]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cultural practice in 29 countries.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1602]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Type </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in Africa.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1603]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Done between Age of infancy &amp; up to 15yrs.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1604]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>50% below 15yrs.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1605]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>137,000 women in UK have FGM.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1606]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>10,000 under 15yrs.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1607]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Commonest in Somalia 98%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1608]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Guinea 96%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1609]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Complications of FGM: </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1610]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Short term:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1611]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hemorrhage </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>(5 – 62%).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1612]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Urinary Retention </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>(8 – 53%).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1613]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Genital Swelling </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>(2 – 27%).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1614]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fever</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1615]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Infection </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1616]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Long term:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1617]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Genital scarring:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1618]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Keloid 3%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1619]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Epidermoid inclusion cyst</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1620]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sebaceous cyst</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1621]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Neuroma of clitoris</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1622]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Urinary Track Complications:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1623]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>More</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in Type </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>2</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &amp; Type </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>3</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1624]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Urinary obstruction</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>leads to</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> stasis of urine</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>(1. Recurrent U</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>t</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>i</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>,</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> 2. urinary calculi, 3. vaginal calculi)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1625]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>t/m</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> is de-infibulation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1626]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Urinary</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>str</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>icture</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>/</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>fistula</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> referred</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to urologist or urogynaecologist.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1627]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hampers urodynamic testing.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1628]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Sexual functions:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1629]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dyspareunia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1630]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Apareunia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1631]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vulvovaginal lacerations</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1632]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Absence</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> of sexual sensitivity</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1633]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Decreased sexual</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> desire, Arousal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Orgasm</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1634]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Decrease</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> lubrication</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1635]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Poor sexual satisfaction </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1636]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Psychological:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1637]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PTSD</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1638]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anxiety</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1639]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Flashbacks</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1640]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Menstrual disorders:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1641]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Haematocolpus</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1642]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dysmenorrhea</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1643]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>C/section</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1644]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Genital trauma</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1645]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ENND</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1646]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Still birth</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1647]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Need for resuscitation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1648]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Genital infections:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1649]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>bacterial vaginosis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, HSV – 2 </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1650]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Similar risk of chlamydia gonorrhea, syphilis, PiD</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1651]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Infertility:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1652]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Primary due to sexual problems and ascending infection</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1653]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Viral infections:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1654]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hep B, C, HIV</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1655]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Obs</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>tetric</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> complications:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1656]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PPH</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1657]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Prolong labor – C/section</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1658]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Genital trauma</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1659]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ENND</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1660]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Still birth</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1661]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Need for resuscitation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1662]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>FEMALE GENITAL MUTATION ACT:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1663]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FGM is illegal unless done</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> until.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1664]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> (1). For physical/Mental health of women.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1665]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>  </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>(2). Purpose </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>labor/Birth.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1666]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FGM – arranging, facilitation</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Assistance is illegal.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1667]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Offence for those with parental responsibility to fail to protect a girl from risk of FGM.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1668]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FGM in &lt;18 years’ girl Report to </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>police </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>within 1 month.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1669]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Female Genital cosmetic surgery FGCS (including tightening)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1670]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Prohibited unless for physical/mental health.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1671]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Surgeons should make sure compliance with FGM act.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1672]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Infibulation</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> is illegal – No justification.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1673]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> Legal and regulatory </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>responsibilities </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>of health professionals:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1674]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Data recording:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1675]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Data recording is mandatory for all women identified as having FGM.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1676]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Document FGM diagnosis in medical records (even if the FGM is</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> not</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> the reason for presentation).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1677]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If genital examination is performed and type of FGM is identifies, record FGM type (WHO classification).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1678]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Document further details in accordance with the HSCIC FGM Enhanced Dataset.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1679]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Explain to the woman that her personal data will be transmitted to the HSCIC for the purpose of FGM prevalence monitoring and that the data will not be anonymized.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1680]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Reporting to police and/or social services in the eve</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>n</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>t of risk to a child:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1681]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Children under 18:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1682]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If FGM is confirmed (on examination or if the patient or parent says it has been done). Refer as a matter of urgency to the police and this should be done within 1 month of confirmation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1683]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If FGM is suspected (but not confirmed) or the girl is at risk (but has not had FGM), refer to social services or the police. The urgency of the referral depends on the degree of risk.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1684]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Non pregnant women with FGM:</strong></em></span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> </strong></em></span><span class="mm-run" style=''color: ##FF0000; font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>no requirement to report unless a related child is at risk.</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1685]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Pregnant women:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1686]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A member of the clinical team) midwife or obstetrician) must make an individual risk assessment using an FGM safeguarding risk assessment tool ad if the unborn child, or any other child in the family, is considered to be at risk of FGM then reporting to social services or the police must occur</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Document maternal history of FGM in the personal child</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>health record </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>(‘Red book’)</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> prior to postnatal discharge.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1687]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If delivery of a baby girl, notify the designated child protection midwife, who </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>should</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> inform</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> the GP and health visitor.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1688]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt;&gt;&gt;</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Genital piercing should be classified as type 4 FGM in accordance with the WHO FGM classification.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1689]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> Clinical management of adult women with FGM in obstetric and gynecological practice</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1690]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>All acute trusts/health boards should have a designated consultant and</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>midwife responsible for the care of women with FGM.</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1691]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> All women in obstetric and gynecological practice.</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1692]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Explain law on FGM, documenting the discussion and referring her to information provided</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1693]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Provide interpreter if required (not a family member).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1694]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Offer referral for psychological assessment and treatment. </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1695]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Offer specialist referral as appropriate, e.g. sexual health, urology.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1696]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Make a clinical assessment of FGM (symptoms, examination) and need for de-infibulation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1697]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Record data in accordance with the HSCIC FGM Enhanced Dataset. These include age at FGM, country where FGM was performed, date of entry to UK (if applicable) and past history of de-infibulation and/or re-infibulation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1698]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If de infibulation is indicated, offer before pregnancy it can usually be performed on an outpatient basis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1699]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ideally before 1st intercourse</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1700]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Reporting to social services or the police is only required if a related child is considered to be at</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>risk.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1701]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Additional management in pregnant women.</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1702]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Refer to designated consultant obstetrician or specialist midwife with responsibility for women with FGM.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1703]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Local protocols will determine which elements of care (child safeguarding risk assessment, data recording, clinical management) should be undertaken by the designated midwife or obstetrician and which may be undertaken by other appropriately trained midwives or obstetricians.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1704]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Discuss and clearly document </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a plan of care</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> preformatted </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Performa’s</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>may be used.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1705]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Make an individual risk assessment using an FGM safeguarding risk assessment tool (an example of such a tool. If the unborn child or any related child is considered to be at risk then reporting to social services or the police must occur.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1706]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ll women</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>  with FGM are </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>offered</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> psychological assessment is t/m.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1707]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Offer screening for hepatitis C in addition to routine screening for hepatitis B, HIV and syphilis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1708]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>If de-infibulation is indicated, discuss, agree and document the timing (antenatal or intrapartum). Inform the woman that re-infibulation after delivery will not be performed under any circumstances.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1709]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Manage as high obstetric risk (increased risk of hemorrhage, perineal trauma and caesarean section), except for women who have had previous pregnancies with uncomplicated vaginal deliveries and no history of post-delivery re-infibulation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1710]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Document maternal history of FGM in the personal child health record (''Red Book'') prior to postnatal discharge.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1711]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>If delivery of a baby girl, notify the designated child protection midwife, who should inform the GP and health visitor.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1712]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Offer postnatal follow-up if de-infibulation performed intrapartum or if planned de-infibulation did not occur because of delivery by caesarean section.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1713]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Indications for De-Infibulation:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1714]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> Too tight introits to allow menstrual flow</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> vaginal examination, normal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>urination</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> or comfortable sexual intercourse &amp; safe vaginal delivery</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1715]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Before gynecological surgery</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> TOP</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Cervix</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Smear, Sexual health scre</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ening</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1716]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Type </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>III</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1717]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 16pt''><u><strong>Plan of care for women with FGM</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 16pt''><u><strong> in</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 16pt''><u><strong> pregnancy:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1718]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 9pt''>-  Document maternal history of FGM in personal child health record (Red Book'').</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 9pt''>-  If delivery of baby girl, notify safeguarding midwife who should inform the GP and health visitor.</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 9pt''>-  Offer postnatal follow-up if de infibulation performed intrapartum er if planned de-infibulation did not occur because of delivery by caesarean section</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 9pt''>-  Ensure all data required for HSCIC Enhanced Dataset have been recorded.</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 9pt''>-  Generally, manage as high risk for caesarean section, hemorrhage and perineal trauma</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 9pt''>-  Some women may be considered low risk and suitable for midwifery-led care if history of previous uncomplicated vaginal delivery</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 9pt''>-  If de-infibulation is required, ensure that the midwife and obstetrician caring for the woman have received appropriate training</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 9pt''>-  Perineal tears in women with FGM should be managed in the same manner as in women without F</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 9pt''>G</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 9pt''>M.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''><em><strong>-  Use professional interpreter if required (not family member) and explain law on FGM.</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''>-  Offer referral for psychological assessment and screening for hepatitis in addition to routine antenatal screening.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''>-  Make clinical assessment of FGM. If de infibulation is required, agree timing and explain that re-infibulation will not be performed.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''>-  Assess other obstetric risk factors and action appropriately.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''>-  Agree and Document plan for antenatal, intrapartum and postpartum care.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>postpartum</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>intrapartum</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>antenatal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><strong>Clinical management plan:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>-  Ensure clear documentation</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>-  Preformatted pro</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>f</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>orm</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>s may be used</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><strong>Woman with FGM in pregnancy:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''>Referral to designated midwife and/or obstetrician with responsibility for FGM Consultant-led care</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><strong>Data recording:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><strong>-  </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Ensure compliance with HSCIC Enhanced Dataset.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>-  Document FGM diagnosis, including FGM type (WHO classification).</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''><strong>Child safeguarding risk assessment by midwife or obstetrician:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''>-  </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''>Use risk assessment tool</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''>-  </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''>Explain law on FGM</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''>-   </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''>Report to social services or the police if unborn child or related child at risk.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 16pt''><u><strong></strong></u></span></p>', 0);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-01-021-1', 't-mm-01-021', 'document_html', '<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1719]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>De-infibulation</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> can be done</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1720]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>antenatally</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1721]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> stage of labour</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1722]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>@</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> the</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> time of delivery</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1723]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Before or</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> after </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>C/S</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1724]"> </p>', 1);

