INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-02-004-0', 't-mm-02-004', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-02-004" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2385]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''><u><strong>MANAGEMENT</strong></u></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''><u><strong> OF MALE PARTNER</strong></u></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2386]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Surgical</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Obstructive </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Azoospermia</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Surgical correction o</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>r sperm retrieval + IVF</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Hydrocele </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Surgery is</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>NR as treatment of infertility.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2387]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>                    </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Medical </strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2388]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Idiopathic:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No role of:</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Antiestrogens.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Gonadotrophins.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Androgens.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bromocriptine</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Kin</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>in </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>enhancing drugs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Anti – sperm Antibodies +ve</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Role of steroid</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> is</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> unclear.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Antib</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>iotic. Given:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>When leukocytes present along with identified infection.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Ejaculatory Failure:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Can be </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Corrected without need for IVF.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2389]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypogonadotropic</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2390]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypogonadism</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2391]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2392]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Gonadotrophins.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2393]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2394]"> </p>
