INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-02-005-0', 't-mm-02-005', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-02-005" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2408]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>MANAGEMENT</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''> OF FEMALE PARTNER:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2409]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2410]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Tubal/uterine factors</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>(where expertise are present).</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Ovulation disorders</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>WHO Classes</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Class I</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>: </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypogonadotropic </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypogonadism</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>increase</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>BMI if &lt;19</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Moderate </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>exercise</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>pulsatile</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GnRH </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>analogues</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Or</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Gonadotrophins</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>With LH</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> activity</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Induce </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ovulation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2411]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2412]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Class II</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypothalamic pituitary </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ovarian </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''><strong>1</strong></span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''><sup><strong>st</strong></sup></span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''><strong> line: clomiphene citrate</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> BMI if &gt;30</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CC or Met</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>formin</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or Comb</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ination</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Acc to BMI</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>CC:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> - USG monitoring of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>@ least </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1 cycle</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to know the ovarian response</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Don’t use for &gt;6 cycles</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>CC failure</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>IVF</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2413]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Uterine:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Adhesiolysis via hysteroscopy in case of asherman </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>syndrome</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Tubal disease</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Mild:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>=&gt;</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> microsurgery &amp; laparoscopic surgery improves chances of conception.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tubal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Caut</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>erization</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or can</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ulation in proximal blockade</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>sa</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lpingography + selective </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>catheter</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ization</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hysteroscopy tubal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cannulation</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Salpingectomy before IVF</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> if</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hydrosalpinx</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
