INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-02-009-0', 't-mm-02-009', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-02-009" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2693]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>3. FERTILITY PRESERVATION</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2694]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Embryo, Egg, sperm – </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2695]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cryopreservation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2696]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Use liquid nitrogen vapor.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''><strong>NICE</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2697]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>10 years’ storage.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2698]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Cryopreservation:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2699]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Co</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ol</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ing of cells/tissues to sub – zero temperature – 196`c.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2700]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Slow cooling of liquid nitrogen.</span></p>
