INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-02-014-0', 't-mm-02-014', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-02-014" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3068]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>8. EARLY OVARIAN AGING:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3069]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Definition:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3070]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Low ovarian r</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>eserve @ young age and accelerated loss of ova</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>rian follicle in early thirties/ before 40 yr </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>age</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3071]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>EOA includes all women who attai</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>n Menopause before 45 years</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3072]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>EOA is precursor to early Menopause or POI</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3073]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Incidence: 10% overall</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3074]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Etiology: RF</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3075]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Genetic factors</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3076]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Smoking </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3077]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Infections</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3078]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Autoimmune</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3079]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fetal environment</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> i</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>n utero factors</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3080]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Chemo/Radio</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3081]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Endometriosis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3082]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Consequences:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3083]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Subfertility – early loss of fertility due t</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>o depletion of ovarian reserves</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3084]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Aneuploid</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>y</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3085]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Miscarriage</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3086]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>POI =&gt; </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>long term consequences</u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3087]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Osteoporosis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3088]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cardio vascular effects</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3089]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Urogenital problems</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3090]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>Gonadal age</u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3091]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>more in</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> women</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> with EOA</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3092]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>How to </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>counse</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>l regarding fertility:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3093]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Don’t delay</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3094]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cons</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ervative/natural conception 18%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3095]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IUI 15%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3096]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Fertility preservation:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3097]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Embryo preservation – </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>couple</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3098]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Oocyte preservation – single women</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3099]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Or emb</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ryo preservation with donor egg</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3100]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IVF.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3101]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Prevention:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3102]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fertility </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Educat</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ion</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>to couples and women.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3103]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Educate girls </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>regarding fertility in schools</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3104]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Stem cell therapy – being tried</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3105]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mi</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tochondrial transfer being tried</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3106]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Antioxidants to reduce apoptosis like CO – Q10.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3107]"> </p>
