INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-02-015-0', 't-mm-02-015', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-02-015" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3121]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>9. LONG TERM CONSEQUENCES OF PCOD:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3122]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Incidence=</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 2.2 – 26%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3123]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>More in South Asians.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3124]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Commonest Endocrine problem in females</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3125]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Diagnosis:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3126]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rotterdam Criteria: 2 out of 3</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3127]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>In adolescent :3 out of 3</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3128]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PCO on USG – 12 or more follicles or 2 – 9mm</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or ovarian</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> volume &gt;10ml</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>3</sup></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3129]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Oligo/anovulation </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3130]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Clinical/Biochemical </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>hyperandrogenism</span></p>
