INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-02-017-0', 't-mm-02-017', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-02-017" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3437]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>ENDOMETRIOSIS:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3438]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Incidence </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6 – 10% </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3439]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>50% among infertile women.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3440]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Suspect Endometriosis:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3441]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1 or more of the following:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3442]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CPP</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3443]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dysmenorrhea affecting daily activities and QoL</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3444]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dyspar</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>eunia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> (during or after sex)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3445]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Period related/cyclical G.I symptoms.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3446]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Period related/cyclical urinary symptoms:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3447]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dysu</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ria</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3448]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hematuria</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3449]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Infertility + 1 or more of above.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3450]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Assessment:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3451]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Circumstances</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3452]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Priorities – cultural/religious belief.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3453]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fertility desires.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3454]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>QOL.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3455]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Discuss</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>: - pain and symptoms diary.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3456]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Offer</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>: - P/A and P/V exam</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ination</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in all Pts. P/R in rectal disease.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3457]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Consider</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>: - USG – TVS </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3458]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Even P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A, P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>V examination is normal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3459]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>To identify deep</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> endometriosis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>endometriomas</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3460]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>TAS if TVS is no</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>t</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> appropriate</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3461]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>MRI:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3462]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Don’t use as 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> line investigation =&gt; 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> line only in:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3463]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Mullerian anomalies.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3464]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>CA C</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>ervix</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> – staging.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3465]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Before UAE for fibroid mapping</span><span class="mm-run" style=''color: ##FF0000; font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3466]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>D</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>iagnostic</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> Laparoscopy:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3467]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Consider </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lapar</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oscopy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in suspected endometriosis even USG is </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>normal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3468]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Done by </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Gynecologist </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>skilled/ trained in </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lapar</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oscopy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> surgery.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3469]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Take biopsy:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3470]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>To diagnose (negative biopsy don’t exclude </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>ndo</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>metriosis</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3471]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>To rule out malignancy if endometriosis is not excised (1 – 2% risk of Malignancy with endometriosis).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3472]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>USG/MRI before </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lapar</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oscopy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> if deep endometriosis is suspected.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3473]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Full systematic </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lapar</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oscopy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>normal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> =&gt; Explain that there is no endometriosis consider another diagnosis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3474]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Discussion before </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>lapar</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>oscopy</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> involves:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3475]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>What </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lapar</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oscopy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> involves &amp; </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>surgical treatment (with Pt cons</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ent).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3476]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Benefits and risks of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lapar</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oscopy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3477]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Effect of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lapar</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oscopy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> on symptoms.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3478]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Need for further surgery that is </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>not </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>planned like deep endom</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>etriosis bowel, bladder, ureteric surgery</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3479]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>                                      </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Management</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3480]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3481]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Long term support due to significant</span></p>
