INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-03-004-0', 't-mm-03-004', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-03-004" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3963]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>OVARIAN CYST IN POST-MENOPAUSAL WOMEN:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3964]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Incid</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>nce of cyst = 5 –</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>7% (simple cysts).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3965]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Clinical presentation:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3966]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Acute pain – cyst accident.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3967]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Work – up of PMB.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3968]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Incidental findings.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3969]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Initial assessment by CA – 125 &amp; TVS.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3970]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>History:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3971]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk factor</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> of</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> malignancy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3972]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Symptoms of malignancy (same as</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in premenopausal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3973]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Family history of CA ovary, bowel and Breast.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3974]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Women is high risk of CA if she is 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> degree relative of Cancer Affected.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3975]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Significant family Hx:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3976]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>&gt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 2 cases of malignancy who r 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> degree relative of each other</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3977]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>1 </u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>case of CA ovary </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>at </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>any age +1 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>case of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CA breast, &lt;50years relative of each other’s.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3978]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1 case of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CA </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ovary </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>at </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>any age + 2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> cases of</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> CA breast &lt;60years relative of each other.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3979]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3 or more cases of CA colon</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3980]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>OR</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3981]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>In 2 generations + diagnosed before 50 + 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''> degree relative</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>2 </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>CA</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> colon + 1 CA stomach.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3982]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>OR</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3983]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>2CA colon + 1 CA ovary.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3984]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>OR</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3985]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>2 CA colon + 1 CA endometrium</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3986]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>OR</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3987]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>2 CA colon + 1 CA Bladder </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3988]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1 individual with CA ovary + CA breast.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3989]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3990]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Referral to regional center</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> for</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Genetic Services.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3991]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IBS for 12m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> + Age &gt;50years or Fx of CA =&gt; appropriate tests to rule out malignancy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3992]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Physical Examination:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3993]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>15 – 51% sensitivity.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3994]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ascites, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>+</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> mass =&gt; urgent referral.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3995]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Tumor makers:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3996]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CA – 125 – 78% Sen</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>sitivity</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &amp; Spec</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ificity</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to differentiate between </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>benign</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and malignant.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3997]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HE4 – fewer false positive than CA – 125, not raised in Endometriosis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3998]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CEA</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[3999]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CDx</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4000]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cancer Antigen 72 – 4.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4001]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CA – 19</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 9.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4002]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>α</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FP</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4003]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>LD</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>H</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4004]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>B</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HCG. </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4005]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>USG:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4006]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>TVS</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> = single most effective way.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4007]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>TAS </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>= Not used in isolation. Used as supplementary tool with TVS if mass is beyond the field of TVS. </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4008]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Description of cyst on TVS detailed features:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4009]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Simple:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4010]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>95 – 99% benign.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4011]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Thin wall</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4012]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Post acoustic shadow.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4013]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anechoic fluid.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4014]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Absence of septa</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tion or nodules, in </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>multilocular</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4015]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Incomplete septa</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tion</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Papilla &lt;3 cm.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4016]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Complex:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4017]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Complete </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>septation</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4018]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Solid n</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>odules.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4019]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Papillary projection &gt; 3cm.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4020]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>In multilocular cyst risk of malignancy is 8%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4021]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>In solid components 36 – 39%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4022]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Doppler</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – no used routinely.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4023]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Spectral/pulsed Doppler</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – not used routinely</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4024]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>3D USG</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – Not used routinely</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4025]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Power Doppler</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – help to differentiate between benign and malignant by detecting blood flow in papilla centrally or solid components.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4026]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>CT scan</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4027]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Not used routinely as P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> tool.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4028]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Suspicion of malignancy on the basis of clinical Pic</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ture,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> USG, and tumor, makers</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4029]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>CT scan</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> of abd</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>omen</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> + pelvis</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to stage the d</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>isease</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>. And to differentiate between P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &amp; II</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> cancer</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4030]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Do oncology r</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ef</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>rr</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>al</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> after </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CT scan</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4031]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>MRI:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4032]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Not used as P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> tool routinely.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4033]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>nd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> line imaging for characterization of indeterminate ovarian cyst when USG is inconclusive.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4034]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Contrast enhanced MRI has superior certainty.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4035]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>PET – CT:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4036]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No clear Advantage.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4037]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Scoring systems:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4038]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>RMI</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4039]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>OVA 1: &gt;4.4 high risk of malignancy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4040]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ROMA: CA – 125, HE</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>4</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and menopausal Status</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4041]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>             &gt; 2.27 =&gt; high risk of malignancy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4042]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IOT</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A: in</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Pre-Menopausal, overall IOTA</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>has </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>better linear regression </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IOTA is better than RMI. </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4043]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>RMI:</strong></u></span></p>
<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;margin-left:0pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:72.1pt;"><col style="width:36.75pt;"><col style="width:66pt;"><col style="width:76.65pt;"></colgroup><tbody><tr><td style="white-space:pre-wrap;width:34.25pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Risk </p></td><td style="white-space:pre-wrap;width:68.25pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">RMI value</p></td><td style="white-space:pre-wrap;width:81.55pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Risk of Malignancy</p></td><td style="white-space:pre-wrap;width:85.05pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Treatment by</p></td></tr><tr><td style="white-space:pre-wrap;width:34.25pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Low</p></td><td style="white-space:pre-wrap;width:68.25pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">&lt;25</p></td><td style="white-space:pre-wrap;width:81.55pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">&lt;3%</p></td><td style="white-space:pre-wrap;width:85.05pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">General Gynaecologist </p></td></tr><tr><td style="white-space:pre-wrap;width:34.25pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Intermediate</p></td><td style="white-space:pre-wrap;width:68.25pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">25 – 250 </p></td><td style="white-space:pre-wrap;width:81.55pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">20%</p></td><td style="white-space:pre-wrap;width:85.05pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Lead clinician in cancer unit</p></td></tr><tr><td style="white-space:pre-wrap;width:34.25pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">High </p></td><td style="white-space:pre-wrap;width:68.25pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">&gt; 250 </p></td><td style="white-space:pre-wrap;width:81.55pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">70%</p></td><td style="white-space:pre-wrap;width:85.05pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Oncologist in cancer Centre.</p></td></tr></tbody></table></div>
