INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-03-005-0', 't-mm-03-005', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-03-005" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4127]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>5. </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>OVARIAN CYST IN CHILDREN AND ADOLESANTS (TEENS 13 – 15 YEARS).</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4128]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Peak incidence:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> year of life or around </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>menarche</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4129]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Commonest cause of a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>bdominal cyst in fetus and Neona</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tes. More common in 3</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>rd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> due to   mater</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>na</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>l E</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>strogen</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, fetal Gonadotropin, pla</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ce</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ntal HCG. </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4130]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Complication of Cyst: </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4131]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Torsion, rapture, Hge, pressure on other organs.</span></p>
