INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-03-007-0', 't-mm-03-007', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-03-007" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4317]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>BORDERLINE OVARIAN TUMORS (</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>BOT</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>)</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4318]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tumors of low malignant potential.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4319]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>More in young Pts.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4320]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>10 – 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5% of all epitheli</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>al ovarian neoplasm.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4321]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5-year survival:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4322]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Stage I = 95 – 97%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4323]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Stage II = 50 – 86%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4324]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>10 years’ survival 70 – 80%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4325]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Risk Factor: </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4326]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>S</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ame as Epithelial tumors</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4327]"><span class="mm-run" style=''color: ##FF0000; font-family: "Calibri", sans-serif; font-size: 8pt''>Ser</span><span class="mm-run" style=''color: ##FF0000; font-family: "Calibri", sans-serif; font-size: 8pt''>ous neoplasia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>N</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>o association with BRCA</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4328]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>p53 mutation = invasive neoplasia </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4329]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>KRAs/BRAF = BOT.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4330]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No progression from 1 form to other.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4331]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>B</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>OT</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> can be invasive but low Grade.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4332]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Histopathology:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4333]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Serous.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4334]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mucinous.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4335]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Endometrial. </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4336]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Serous:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4337]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Most common 50%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4338]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Micropapillary</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4339]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Micro invasive.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4340]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Mucinous:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4341]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>46%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4342]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Intestinal</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4343]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Endometrial:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4344]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bru</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ner.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4345]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Clear.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4346]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mixed.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4347]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Histological features of BOT:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4348]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Stratified epithelium.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4349]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Varying degree of Atypia.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4350]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Ed mitotic activity.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4351]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Lack of stromal invasion (distinguishing feature).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4352]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Symptoms:</strong></u></span></p>
