INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-04-004-0', 't-mm-04-004', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-04-004" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5387]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>POST VOID VOLUME</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5388]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>USG is preferred over Cather.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5389]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Detects Voiding problems.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5390]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Done in Recurrent UTI.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5391]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If &gt;100ml – consider abnormal.</span></p>', 0);

