INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-04-008-0', 't-mm-04-008', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-04-008" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5504]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>OVER ACTIVE BLADDER TREATMENT</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5505]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Life style: all women with OAB</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5506]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Coffee intake</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5507]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fluid intake</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5508]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>W</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>eight</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> if BMI &gt; 30</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5509]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Exercise.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5510]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Treatment of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>precipitating</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> factors – cough, constipation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5511]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>1</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup><u><strong>st</strong></u></sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> line: </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>(Mix + OAB).</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5512]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bladder Retraining.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5513]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6weeks minimum =&gt; </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>up to</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5514]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Combination of medicine + Bladder Retraining if Frequency is the problem.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5515]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>2</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup><u><strong>nd</strong></u></sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> line:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Medical Treatment Anticholinergics.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5516]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Oxybutynin – 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> line, Avoid in old </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>age due to </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CNS effects.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5517]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tropsium – suitable for old </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>with </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CNS </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>problem</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> (</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Don’t</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> cross BBB</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5518]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Darifenacin</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – suitable for old.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5519]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tolterodine.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5520]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Transdermal: if </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>women</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> can’t tolerate orally or severe S/E.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5521]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mirabegron</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>: B</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>3</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Agonist</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>avoid in </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>uncontrolled HTN.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5522]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>              </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>S/E = Eyelid edema, Rash, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tachycardia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5523]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Desmopressin = nocturia avoid </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>if age is </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt; 65 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>with</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> HTN</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5524]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em>S/E of Anti </em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em>Muscarinic</em></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5525]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dry mouth</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>88%,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>constipation</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> blurred vision</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5526]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dry eye, urinary retention.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5527]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>F/U after 4 weeks.</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5528]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5529]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Successful</strong></u></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Not</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Successful</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5530]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5531]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- Change dose.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5532]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Review annually</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> young.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- Alternative</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5533]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6 monthly</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &gt; 75 years.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>  Treatment.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5534]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Combinations</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##EE0000; font-family: "Calibri", sans-serif; font-size: 12pt''>failed</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>MDT</strong></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- Urodynamics.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5535]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>F/U before 4 weeks:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5536]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>In case of troublesome S/E</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5537]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Offer alternatives or transdermal preparations</span></p>
