INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-04-010-0', 't-mm-04-010', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-04-010" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5635]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>SUI - STRESS URINARY INCONTINENCE &amp; ITS STEP WISE MANAGEMENT</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5636]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>1</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup><u><strong>st</strong></u></sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> line:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5637]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Life style:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5638]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PFMT – 8 contractions </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>three time a day for</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 3m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5639]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Supervised by physiotherapist.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5640]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Continue if effective.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5641]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Don’t use Electrical stimulation and/ or bio feed</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>back</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> alone or in combination with PFMT</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5642]"><span class="mm-run" style=''color: ##EE0000; font-family: "Calibri", sans-serif; font-size: 9pt''>Failed </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>should be considered if women can’t actively cont</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>r</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>act pelvic flour muscles to aid motivation and </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>adherence</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to therapy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5643]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>MDT:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5644]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>2</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup><u><strong>nd</strong></u></sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> line:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> surgical treatment.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5645]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Colposuspension ideal – space of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Reitzes</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, cooper’s ligament</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> either</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> trans</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>peritoneal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> retroperitoneal.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5646]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rectus Fascial sling.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5647]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Intra mural bulking agents.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5648]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If other procedures are not suitable.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5649]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Permanent injectable material.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5650]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Less effective than surgery.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5651]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mid ureteral </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mesh sling</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> procedures.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5652]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Retropubic </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5653]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tans obturator</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> not recommended unless previous surgery</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5654]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Type 1 macro porous polypropylene mesh.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5655]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Artificial </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>sphincters</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> = Not Recommended.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5656]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Unless surgery failed.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5657]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5658]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5659]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Procedures Not Recommended:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5660]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>M – M </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Krants</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5661]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Colporrhaphy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5662]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Needle suspension.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5663]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Para vaginal defect repair.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5664]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Porcine dermis sling.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5665]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5666]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Follow – up after surgery.</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5667]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>With 6m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5668]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Retro pubic sling:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5669]"><span class="mm-run" style=''color: ##EE0000; font-family: "Calibri", sans-serif; font-size: 9pt''>Failed </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vaginal examination to check for mesh extrusion or exposure.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5670]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5671]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>MDT</strong></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Mesh Extrusion</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5672]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Urodynamics.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5673]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>3</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup><u><strong>rd</strong></u></sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> line:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5674]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Medical Treatment</strong></u></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>&lt;1cm</strong></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>&gt;1cm</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5675]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pt refuses surgery.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5676]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Unfit for surgery</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>    </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>           </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Off</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>er</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> estrogen</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>       Remove</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5677]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>for 3 months</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5678]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Duloxetine is</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Drug of choice.</span></p>
