INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-04-011-0', 't-mm-04-011', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-04-011" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5697]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>URINARY RETENTION</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5698]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5699]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>MSU</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5700]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cath</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>et</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>erize </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>for </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>24 – 48hrs.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5701]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ntibiotic</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> cover.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5702]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5703]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Remove gradually</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5704]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5705]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pt voids                                               </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>D</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>on’t void.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5706]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Retain catheter for 7 days.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5707]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A/B cover.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5708]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CUE for infection.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5709]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rule out F.B or hematoma.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5710]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5711]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Don’t void after 7 days.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5712]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5713]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Refer to urologist or urogynaecologist.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5714]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5715]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5716]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5717]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5718]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5719]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5720]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5721]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5722]"> </p>
