INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-04-012-0', 't-mm-04-012', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-04-012" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5725]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>BLADDER PAIN SYNDROME</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5726]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Incidence 2.3 – 6.5%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5727]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Diagnosis by exclusion</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5728]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pain, pressure or discomfort + urgency/ frequency/ </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>nocturia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/ persistent urge to void.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5729]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5730]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Over 6 weeks – 6</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>months sometimes for years</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5731]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>With no </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>identifiable</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> cause.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5732]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>History:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> RULE OUT</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5733]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>UTI</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5734]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Calculi</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5735]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pudendal nerve entrapment</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5736]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Radiation</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5737]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Drugs -ketamine</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5738]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Urethral diverticula</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5739]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Diverticular disease</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5740]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>STI</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5741]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>B</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> outlet obstruction </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Endometriosis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5742]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Autoimmune</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Prolapse</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5743]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IBS</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>OAB</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5744]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vulvodynia.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Malignancy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5745]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vulvodynia        </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bladder calculi</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5746]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fibrinolysis.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>                   </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Infection</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5747]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Chronic fatigue.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5748]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Pain:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5749]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Location, type, relationship to bladder Filling and emptying.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5750]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Triggering factors, onset.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5751]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Rule out Abuse:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5752]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Examination:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5753]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rule out Bladder distention.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5754]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hernia, trigger paints, prolapse.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5755]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vulval skin, bladder</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> skin</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5756]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Look for vulval, urethral, bladder tenderness</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5757]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Investigations:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5758]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bladder diary</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> for 3 days, frequency volume chart</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5759]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Food diary</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5760]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dip stick</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> testing</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5761]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>MSU –ve but patient is symptomatic – rule out </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ureaplasma</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &amp; Chlamydia.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5762]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cytology –</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>to </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>rule</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> out</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> microscopic-hematuria.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[5763]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sterile</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-pyuria </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>=&gt;</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> acid fast bacilli.</span></p>
