INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-05-003-0', 't-mm-05-003', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-05-003" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6294]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>PID</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6295]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>includes:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6296]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Endometritis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6297]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Salpingitis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6298]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Oophoritis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6299]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tubo – ovarian abscess</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6300]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pelvic peritonitis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6301]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>D/D:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6302]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>UTI</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6303]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ectopic </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6304]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ovarian cyst complications.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6305]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Appendicitis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6306]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Functional pain</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6307]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Endometriosis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6308]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>C</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>ausative</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> Agents:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6309]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3% gonococcal</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6310]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>14 – 35% CT</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>¼ of PiD in UK</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6311]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4 – 6 weeks after IUCD</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6312]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Others:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6313]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Gardnella</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6314]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anaerobes</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6315]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mycoplasma – emerging agent.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6316]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Symptoms:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6317]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Lower abdominal pain</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6318]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Deep </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>dyspareunia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6319]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>AUB</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6320]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IMB</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6321]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PCB</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6322]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Menorrhagia.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6323]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Abnormal discharge</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6324]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Signs:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6325]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>B/L tenderness in lower </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>abdomen</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6326]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Adnexal tenderness</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6327]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cervical motion tenderness</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6328]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fever &gt; 38</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> C.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6329]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Diagnosis:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6330]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Clinical S/S =&gt; PPV 65 – 90%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6331]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Elevated ESR, CRP</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6332]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Testing for NG &amp; CT.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6333]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Absence of PUS cells on endo cervical &amp; vaginal swabs =&gt; Good NPV 95% but presence has PPV of 17%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6334]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Management:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6335]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Don’t delay – risk of complication</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6336]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Subfertility</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6337]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ectopic</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6338]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CPP</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6339]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fitz hug</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>h</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Curtis syndrome</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6340]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Empirical treatment.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6341]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rest</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6342]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>nalgesia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6343]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Avoid intercour</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>s</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> till they &amp; their partners have completed treatment.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6344]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Partner screening</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> is recommended</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6345]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>OCP + Break through bleeding =&gt; STI screening esp CT.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6346]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>UPT =&gt; Offer</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6347]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Screening for STI including HIV =&gt; offer</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6348]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Out Patient Treatment (Mild – Mod</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>erate</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>):</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6349]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ceftriaxone 1g sta</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>t IM</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6350]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>[14 DAYS]</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>+ Doxi 100mg</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6351]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>+ Flagyl 400 B.D </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6352]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>[14 DAYS]</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ofloxacin</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 400 B.D</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6353]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>+ metronidazole </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6354]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ceftriaxone </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1g sta</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>t I/M</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6355]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>+ </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Az</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>t</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>hro</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 1g/weeks. [14 DAYS]</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6356]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Oral Moxi 400 OD – [14 DAYS]</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6357]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6358]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>M-Gen</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>italium = moxi</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>floxacin</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6359]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pregnancy, B.F – parental therapy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6360]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Severe PID – Consider anaerobes</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6361]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Quinolones – avoided in </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Gonoc</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oc</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> PID due to     ing </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>resistance</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6362]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Don’t use Quinolones as 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> line</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6363]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>I/V in inpatient regimens should be continued 24 hours after clinical improvement.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6364]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Partner</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong> treatment:</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong> </strong></em></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6365]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>z</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>thro</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 1g – single dose.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6366]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Screening in 6m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> duration</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6367]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Avoid sexual </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>intercou</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>r</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>se</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> until index pt h</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ave completed treatment course.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6368]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>TOC:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6369]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2 – 4 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6370]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CT – not routinely if indicated then after 3 – 5weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6371]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>In – Patient:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6372]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Surgical Emergency can’t be excluded.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6373]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No response to therapy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6374]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Severe disease</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6375]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>To Abscess</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6376]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Intolerance to oral treatment</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6377]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pregnancy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6378]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ceftriaxone 2g daily I/v + </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Doxi</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> B.D.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6379]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Followed by</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6380]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Doxi B.D</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6381]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>[14 DAYS]</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>+ Metronidazole B.D</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6382]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Clinda 90mg TDS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6383]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>+ Gentamycin 2mg/kg loading dose then 1.5mg/kg 1day – TDS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6384]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>F.B </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6385]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>[14 DAYS]</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Oral </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>clinda</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 45mg QDS or</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6386]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Doxi 10mg B.D</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6387]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>+ Metronidazole</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6388]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Gentamycin levels should be monitored.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6389]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>I/V ofloxacin 400mg B.D + I/V</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6390]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Metronidazole 500mg TDS – 14days</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6391]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cipro 200 B.D + Doxi + Metronidazole TID = 14 days.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6392]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Surgical management:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6393]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Laparoscopy – divide adhesions &amp; drainage of pelvic abscess.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6394]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>USG Guided aspiration of fluid collection is less invasive but equally effective.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6395]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Adhesiolysis in Perihepatitis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6396]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Follow Up:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6397]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>72 hours in moderate – severe.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6398]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Further review 2 – 4 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6399]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Persistent symptoms, consider</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6400]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>I/V antibiotics</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6401]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rule out resistance.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6402]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Recurrent infection.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6403]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Repeat testing for N.G &amp; CT after 2 – 4 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6404]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6405]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6406]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6407]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6408]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6409]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6410]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6411]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6412]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6413]"> </p>', 0);

