INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-05-004-0', 't-mm-05-004', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-05-004" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6414]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>GENITAL CONDITIONS AND MANAGEMENT:</strong></span></p>
<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;width:599.25pt;table-layout:fixed;margin-left:-15.45pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:79pt;"><col style="width:85.05pt;"><col style="width:113.4pt;"><col style="width:7.1pt;"><col style="width:70.85pt;"><col style="width:78pt;"><col style="width:56.7pt;"><col style="width:56.7pt;"><col style="width:52.45pt;"></colgroup><tbody><tr><td style="white-space:pre-wrap;width:79pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Condition</p></td><td style="white-space:pre-wrap;width:85.05pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Causative Agent</p></td><td colspan="2" style="white-space:pre-wrap;width:120.5pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Clinical features</p></td><td style="white-space:pre-wrap;width:70.85pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Diagnosis</p></td><td style="white-space:pre-wrap;width:78pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Treatment</p></td><td style="white-space:pre-wrap;width:56.7pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Partner tracing and Treatment</p></td><td style="white-space:pre-wrap;width:56.7pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">TOC</p></td><td style="white-space:pre-wrap;width:52.45pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Follow up</p></td></tr><tr><td style="white-space:pre-wrap;width:79pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Donovanosis</p><p style="margin:0;margin-bottom:8pt;">20 – 40years</p><p style="margin:0;margin-bottom:8pt;">More in India</p><p style="margin:0;margin-bottom:8pt;"><figure class="mm-figure" data-mm-figure-id="8c03107c5046852a4796c90b" data-mm-topic-id="t-mm-05-004"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 8c03107c5046852a4796c90b" viewbox="381000 -19050 238125 314325" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="7e0a5c15a6ab77410f6ebf593cd58f81fd783c834ac6e91319e64398dd484ce5"><defs><marker id="arrow-end-059f74935ab22064067f" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#000000"></path></marker></defs><g data-mm-object-id="059f74935ab22064067f" transform="translate(510630 32022)"><g transform="translate(0 0)"><path d="M 0 0 L 1 146957" fill="none" fill-opacity="0" stroke="#000000" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-059f74935ab22064067f)"></path></g></g></svg></figure>   Ing over all</p></td><td style="white-space:pre-wrap;width:85.05pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">Klebsiella</p><p style="margin:0;margin-bottom:8pt;">Granulomatous</p></td><td style="white-space:pre-wrap;width:113.4pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">- Papules</p><p style="margin:0;margin-bottom:8pt;">- S/C nodules that ulcerate.</p></td><td colspan="2" style="white-space:pre-wrap;width:77.95pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Direct Microscopy</p><p style="margin:0;margin-bottom:8pt;">Rapid Giemsa</p><p style="margin:0;margin-bottom:8pt;">Histology</p><p style="margin:0;margin-bottom:8pt;">Donnovan bodies</p><p style="margin:0;margin-bottom:8pt;">PCR</p></td><td style="white-space:pre-wrap;width:78pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"> - Azithro 1g weekly</p><p style="margin:0;margin-bottom:8pt;">- Co – trimoxazole</p><p style="margin:0;margin-bottom:8pt;">- Doxi</p><p style="margin:0;margin-bottom:8pt;">- Erythromycin</p><p style="margin:0;margin-bottom:8pt;">Children Azithromycin</p><p style="margin:0;margin-bottom:8pt;">Pregnancy Erythromycin</p></td><td style="white-space:pre-wrap;width:56.7pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">All in 6m0</p></td><td style="white-space:pre-wrap;width:56.7pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:52.45pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">Till lesions heals</p></td></tr><tr><td style="white-space:pre-wrap;width:79pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">Lymphogranuloma</p><p style="margin:0;margin-bottom:8pt;">venereum</p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">LGV</p></td><td style="white-space:pre-wrap;width:85.05pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">CT L1 – L3</p><p style="margin:0;margin-bottom:8pt;">L2 commonest </p></td><td colspan="2" style="white-space:pre-wrap;width:120.5pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">- 95% Asymptomatic.</p><p style="margin:0;margin-bottom:8pt;">- Painless papules, pustules, shallow ulcers.</p><p style="margin:0;margin-bottom:8pt;">- Hemorrhagic proctitis</p><p style="margin:0;margin-bottom:8pt;">- pharyngeal LGV.</p><p style="margin:0;margin-bottom:8pt;">- Painful lymphadenopathy, lymphadenitis (painful + Tender unilateral)</p></td><td style="white-space:pre-wrap;width:70.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">NAAT:</p><p style="margin:0;margin-bottom:8pt;">- Ulcer base</p><p style="margin:0;margin-bottom:8pt;">- Rectal swabs.</p><p style="margin:0;margin-bottom:8pt;">- Urethral swab</p></td><td style="white-space:pre-wrap;width:78pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">Doxi Erythro</p></td><td style="white-space:pre-wrap;width:56.7pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">Within weeks? Before onset of symptoms</p></td><td style="white-space:pre-wrap;width:56.7pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">Not required routinely</p></td><td style="white-space:pre-wrap;width:52.45pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p></td></tr><tr><td style="white-space:pre-wrap;width:79pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">Chancroid </p></td><td style="white-space:pre-wrap;width:85.05pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">H Ducreyi</p></td><td colspan="2" style="white-space:pre-wrap;width:120.5pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Painful ulcers</p><p style="margin:0;margin-bottom:8pt;">Bubo formations</p><p style="margin:0;margin-bottom:8pt;">Painful lymphadenopathy</p></td><td style="white-space:pre-wrap;width:70.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">NAAT</p><p style="margin:0;margin-bottom:8pt;">Ulcer base</p></td><td style="white-space:pre-wrap;width:78pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Azithromycin</p><p style="margin:0;margin-bottom:8pt;">Ceftriaxone</p><p style="margin:0;margin-bottom:8pt;">Ciprofloxacin </p></td><td style="white-space:pre-wrap;width:56.7pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">All partners within 10 days before symptoms</p></td><td style="white-space:pre-wrap;width:56.7pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">Not required</p></td><td style="white-space:pre-wrap;width:52.45pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p></td></tr><tr><td style="white-space:pre-wrap;width:79pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Syphilis</p></td><td style="white-space:pre-wrap;width:85.05pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left: