INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-05-006-0', 't-mm-05-006', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-05-006" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6671]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>7. ABORTION CLAUSES</strong></span></p>
<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;margin-left:0pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:48.65pt;"><col style="width:227.55pt;"><col style="width:141.75pt;"><col style="width:120.45pt;"></colgroup><tbody><tr><td style="white-space:pre-wrap;width:48.65pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">Clause</p></td><td style="white-space:pre-wrap;width:227.55pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">Definition</p></td><td style="white-space:pre-wrap;width:141.75pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">Example</p></td><td style="white-space:pre-wrap;width:120.45pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">Additional Points</p></td></tr><tr><td style="white-space:pre-wrap;width:48.65pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">A</p></td><td style="white-space:pre-wrap;width:227.55pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Continuation of pregnancy would involve risk to life of the women &gt; Than if TOP done.</p></td><td style="white-space:pre-wrap;width:141.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">PE @ 34 week</p></td><td style="white-space:pre-wrap;width:120.45pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Elective Termination</p><p style="margin:0;margin-bottom:8pt;">2 practioners involved</p><p style="margin:0;margin-bottom:8pt;">In decision</p></td></tr><tr><td style="white-space:pre-wrap;width:48.65pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">B</p></td><td style="white-space:pre-wrap;width:227.55pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Continuation of pregnancy can cause Grave injury to physical and mental health &gt; than if TOP done</p></td><td style="white-space:pre-wrap;width:141.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:120.45pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Elective Termination</p><p style="margin:0;margin-bottom:8pt;">2 practioners involved</p></td></tr><tr><td style="white-space:pre-wrap;width:48.65pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">C</p></td><td style="white-space:pre-wrap;width:227.55pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Social Reasons &lt; 24 weeks</p><p style="margin:0;margin-bottom:8pt;">Injury to physical/ Mental health of women</p></td><td style="white-space:pre-wrap;width:141.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Gender, Rape</p></td><td style="white-space:pre-wrap;width:120.45pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Elective Termination</p><p style="margin:0;margin-bottom:8pt;">2 practioners involved</p></td></tr><tr><td style="white-space:pre-wrap;width:48.65pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">D</p></td><td style="white-space:pre-wrap;width:227.55pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Existing child health &lt; 24 weeks</p><p style="margin:0;margin-bottom:8pt;">Continuation more harm to physical/ Mental health of existing child than TOP</p></td><td style="white-space:pre-wrap;width:141.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Down @ home now requesting TOP that she can’t handle Down and newborn </p></td><td style="white-space:pre-wrap;width:120.45pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Elective Termination</p><p style="margin:0;margin-bottom:8pt;">2 practioners involved</p></td></tr><tr><td style="white-space:pre-wrap;width:48.65pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">E</p></td><td style="white-space:pre-wrap;width:227.55pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Risk of being handicapped if born anomalous fetus</p></td><td style="white-space:pre-wrap;width:141.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Gross anomalies, Edwards Down with associated severe Anomalies </p><p style="margin:0;margin-bottom:8pt;">Cleft, lip, Missing limp =&gt; don’t Abort </p></td><td style="white-space:pre-wrap;width:120.45pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Elective Termination</p><p style="margin:0;margin-bottom:8pt;">2 practioners involved</p></td></tr><tr><td style="white-space:pre-wrap;width:48.65pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">F</p></td><td style="white-space:pre-wrap;width:227.55pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"> To save life of women</p></td><td style="white-space:pre-wrap;width:141.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Eclampsia</p></td><td style="white-space:pre-wrap;width:120.45pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><ul style="list-style-type:none;margin:0 0 0 36pt;padding:0;text-indent:-18pt;"><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Emergency termination</li><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>1 practioner involved </li></ul></td></tr><tr><td style="white-space:pre-wrap;width:48.65pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">G</p></td><td style="white-space:pre-wrap;width:227.55pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Prevent permanent Injury to physical/ mental health of women</p></td><td style="white-space:pre-wrap;width:141.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;text-align:center;margin-bottom:8pt;">SCH</p></td><td style="white-space:pre-wrap;width:120.45pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><ul style="list-style-type:none;margin:0 0 0 36pt;padding:0;text-indent:-18pt;"><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Emergency termination</li><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>1 practioner involved</li></ul></td></tr></tbody></table></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[6672]"><span class="mm-run" style=''color: ##44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>Table </em></span><span class="mm-run" style=''color: ##44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>16</em></span><span class="mm-run" style=''color: ##44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>. </em></span><span class="mm-run" style=''color: ##44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>ABORTION CLAUSES</em></span></p>
