INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-05-008-1', 't-mm-05-008', 'document_html', '<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;margin-left:0pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:48.95pt;"><col style="width:108.1pt;"><col style="width:64.75pt;"><col style="width:104.45pt;"><col style="width:80.95pt;"><col style="width:111.55pt;"></colgroup><tbody><tr><td style="white-space:pre-wrap;width:48.95pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:103pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">Switch from</p><p style="margin:0;text-align:center;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:64.75pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">Switch to</p><p style="margin:0;text-align:center;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:98.65pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">When to start</p><p style="margin:0;text-align:center;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:76.1pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">Requirements for additional contraceptive Precaution</p></td><td style="white-space:pre-wrap;width:111.55pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">Notes</p></td></tr><tr><td style="white-space:pre-wrap;width:48.95pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><ol start="5" style="list-style-type:none;margin:0 0 0 36pt;padding:0;text-indent:-18pt;"><li data-source-marker-codepoints="U+0025 U+0031 U+002E"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">5.</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span></li></ol></td><td style="white-space:pre-wrap;width:103pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">CHC </p><p style="margin:0;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:64.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Another CHC </p></td><td style="white-space:pre-wrap;width:98.65pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Start on day after last No active COC. CVR or CTP</p></td><td style="white-space:pre-wrap;width:76.1pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">No</p></td><td style="white-space:pre-wrap;width:111.55pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">a hormone-free interval (HF1) is taken the need for additional emergency should precautions be and contraception assessed on an individual basis, taking account of correct use before the HPI. See also Table 7. </p></td></tr><tr><td style="white-space:pre-wrap;width:48.95pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><ol start="5" style="list-style-type:none;margin:0 0 0 36pt;padding:0;text-indent:-18pt;"><li data-source-marker-codepoints="U+0025 U+0031 U+002E"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">5.</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span></li></ol></td><td style="white-space:pre-wrap;width:103pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Traditional POP </p></td><td style="white-space:pre-wrap;width:64.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">CHC </p><p style="margin:0;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:98.65pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Can be Immediately. started the POP has been used consistently and </p><p style="margin:0;margin-bottom:8pt;">Correctly </p></td><td style="white-space:pre-wrap;width:76.1pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Yes (7 days") </p><p style="margin:0;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:111.55pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">The primary mode of action Is not inhibition of ovulation and therefore additional precautions are required in case ovulation occurs before contraceptive efficacy of CHC has been established. The cervical mucus effect may be maintained but there is no evidence to prove adequate contraceptive protection. </p></td></tr><tr><td style="white-space:pre-wrap;width:48.95pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><ol start="5" style="list-style-type:none;margin:0 0 0 36pt;padding:0;text-indent:-18pt;"><li data-source-marker-codepoints="U+0025 U+0031 U+002E"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">5.</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span></li></ol></td><td style="white-space:pre-wrap;width:103pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Progestogen-only anovulatory methods </p><ul style="list-style-type:none;margin:0 0 0 36pt;padding:0;text-indent:-18pt;"><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Desogestrel-only pill</li><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Desogestrel-only pill</li><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Injectable </li></ul></td><td style="white-space:pre-wrap;width:64.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">CHC</p></td><td style="white-space:pre-wrap;width:98.65pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><ul style="list-style-type:none;margin:0 0 0 36pt;padding:0;text-indent:-18pt;"><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Start on day after last Desogestrel</li><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Start on day after last Desogestrel up to when the repeat injection is due </li><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span> Start at any time up to when the Implant is due for removal </li></ul></td><td style="white-space:pre-wrap;width:76.1pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">No</p></td><td style="white-space:pre-wrap;width:111.55pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">The primary mode of action of these methods is inhibition of ovulation CHC suppresses ovulation by the time the inhibitory effect of the previous method is lost. </p><p style="margin:0;margin-bottom:8pt;"></p></td></tr><tr><td style="white-space:pre-wrap;width:48.95pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><ol start="5" style="list-style-type:none;margin:0 0 0 36pt;padding:0;text-indent:-18pt;"><li data-source-marker-codepoints="U+0025 U+0031 U+002E"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">5.</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span></li></ol></td><td style="white-space:pre-wrap;width:103pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">LNG-IUS (within licensed duration of use) </p><p style="margin:0;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:64.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">CHC</p></td><td style="white-space:pre-wrap;width:98.65pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Start at any time </p><p style="margin:0;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:76.1pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Yes (7 days" </p><p style="margin:0;margin-bottom:8pt;">if there has been UPSI in the last 7 days, the LNG-IUS should be retained for 7 days </p></td><td style="white-space:pre-wrap;width:111.55pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p></td></tr></tbody></table></div>
