INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-05-021-0', 't-mm-05-021', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-05-021" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[7664]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>CONTRACEPTION IN OVER WEIGHT AND OBESE PEOPLE:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[7665]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Intrauterine Contraception (IUC)</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[7666]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IUC is a </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>highly effective method of contraception</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[7667]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Evidence suggests that its </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>effectiveness is not affected by body weight or BMI</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[7668]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IUC is a </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>safe option</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> for </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>overweight and obese women</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[7669]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Progestogen-only Implants (IMP)</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[7670]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>The </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>etonogestrel (ENG) implant</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> is highly effective and unaffected by body weight or BMI.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[7671]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Licensed duration</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span><br><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>"The licensed duration of ENG implant use of 3 years applies to women of all weight categories."</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[7672]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ENG implant is </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>safe</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> for overweight women and those with obesity.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[7673]"> </p>
<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;margin-left:0pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:155.2pt;"><col style="width:58.25pt;"><col style="width:91.55pt;"><col style="width:148.4pt;"><col style="width:86.1pt;"></colgroup><tbody><tr data-mm-row-height-twips="983" data-mm-row-height-rule="auto"><td style="white-space:pre-wrap;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">Method</p></td><td style="white-space:pre-wrap;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">BMI (kg/m²)</p></td><td style="white-space:pre-wrap;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">UKMEC Category (BMI alone)</p></td><td style="white-space:pre-wrap;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">UKMEC Category (if obesity is a cardiovascular risk)</p></td><td style="white-space:pre-wrap;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">History of Bariatric Surgery</p></td></tr><tr><td style="white-space:pre-wrap;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Combined hormonal contraception (COC, ring, patch)</p></td><td style="white-space:pre-wrap;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">≥30–34</p></td><td style="white-space:pre-wrap;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">2</p></td><td style="white-space:pre-wrap;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">3</p></td><td style="white-space:pre-wrap;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">2</p></td></tr><tr><td style="white-space:pre-wrap;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.