INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-06-029-0', 't-mm-06-029', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-06-029" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9530]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>18. </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>LAPAROSCOPIC MYOMECTOMY:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9531]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Advantages:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9532]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Wound complications</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9533]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Blood loss</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9534]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Post op pain</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9535]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Short hospital stay</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9536]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Disadvantages:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9537]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Emergency TAH 0.3%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9538]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Longer operating time</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9539]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Complications of contained morcellation:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9540]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Upstaging of undiagnosed </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>myosarcoma</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9541]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Peritoneal leiomyomatosis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9542]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Steps to reduce blood loss, intra operatively:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9543]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GnRH analogues, Buserclin, 3.5mg S/C for 3 months.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9544]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vasopressin injection</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9545]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bupivacaine + Adrenaline injection around uterine vessels or around myoma capsule</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9546]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tourniquet placed around uterine vessels.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9547]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9548]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9549]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9550]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9551]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9552]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9553]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9554]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9555]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9556]"> </p>', 0);

