INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-06-030-0', 't-mm-06-030', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-06-030" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9557]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>19. </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>LAPROSCOPY IN PREGNANCY:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9558]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Indications:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9559]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Obstetric and non obstetric</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9560]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Appendicitis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9561]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Choleiystitis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9562]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Adenexal cyst accidents</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9563]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>MDT:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9564]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Decides about whether to go for laproscopy or not</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9565]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>It includes:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9566]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Laprosopic surgeon (senior)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9567]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Gynaecologist</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9568]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anaesthetist</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9569]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Neonatologist</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9570]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>More injuries and risk during pregnancy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9571]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>Counselling</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> includes general complications, uterine perforation, fetal loss, PTL, bleeding.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9572]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>Anaesthesia:</u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9573]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GA</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9574]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Aspiration prophylaxis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9575]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Avoid laryngeal mask airway</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9576]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Maintain B.P, Co</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> levels, End tidal Co</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2 </sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>is the marker.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9577]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>Surgery</u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9578]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Precautions:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9579]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FHR before and after surgery</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9580]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Steroid and Mgso4 if risk of pre – term </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9581]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anti D – if uterine manipulatio occurs</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9582]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tocolysis not required routinely GA acts as tocolytic agent</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9583]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Aovid uterine manipulation</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9584]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Primary port site:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9585]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>According to symphysio fundal height</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9586]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Palmer’s point – N-G decompression while using this site.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9587]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Supraumbilical/ sup xephoid – 3-6cm above umbilical</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9588]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Right midclavicular</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9589]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Secondary port:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9590]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Accordin to SFH</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9591]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ipsilateral to pathology.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9592]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Pneumoperitonium:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9593]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>As non pregnant</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9594]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>CO</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub><strong>2</strong></sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> pressure</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9595]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>maintai</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>n</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> at 10-12mmHg in pregnancy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9596]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9597]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Choice of lapr</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>oscope:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9598]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Followings depends on surgeon’s choice</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9599]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Size 5mm/10mm</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9600]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Degree mostly 30</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9601]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Emergency source </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9602]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Monopolar, Bipolar both safe</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9603]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Drain placement</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9604]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Closure Technique:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9605]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hernia 1 – 2% in incision &gt;10mm</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9606]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Post op antibiotics:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9607]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>According to local protocols</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9608]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Adenexal surgery – don’t require A/B</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9609]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Risks of different procedures:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9610]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Appendicitis -    risk of Miscarriage </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9611]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cholecystits – conservative treatment more complications</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9612]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ovarian cysts – good outcome in 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and 3</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>rd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9613]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cyst aspiratio is safe alternative</span></p>', 0);

