INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-06-032-0', 't-mm-06-032', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-06-032" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9673]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>2</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>1</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>. </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>LAPAROSCOPY IN UROGYNAECOLOGY</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9674]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>UV Prolapse:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9675]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vaginal hystrectomy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9676]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Most common</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9677]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Uterine conservative procedures</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9678]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Laproscopic uterosacral ligament plication</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9679]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk of uretric kinking.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9680]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hysteropexy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9681]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>Risk of:</u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9682]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anterior prolapse</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9683]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Urinary retention</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9684]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Need for further prolapse surgery</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9685]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Vault Prolapse:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9686]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sacrocolpopexy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9687]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Uterosacral ligament suspension</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9688]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Incontine</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>nce procedures:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9689]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Colposuspension</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9690]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Retroperitoneal/ Transperitoneal</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9691]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Preffered option for SUI</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9692]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Plication of paraurethral tissue with cooper’s ligament by applying 2 – 3 suture and correcting vesicourethral angle</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9693]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Midurethral sling – preffferably vaginally</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9694]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9695]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9696]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9697]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9698]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9699]"> </p>', 0);

