INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-07-001-0', 't-mm-07-001', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-07-001" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9852]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>1. RECURRENT PREGNANCY LOSS</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9853]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Work up after 2 miscarriages if abnormality </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>is </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>suspected</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9854]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sggryd – 5% women</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9855]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Risk factors of Recurrent pregnancy loss:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9856]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Age </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9857]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Female </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>&gt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 35yrs</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9858]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Male </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>&gt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 40yrs</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9859]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Previous miscarriages</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9860]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Successful pregnancy after RPL = 60%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9861]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Further loss after RPL = 40%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9862]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Obesity / low BMI</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9863]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>                      </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &lt;19, &gt;25</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9864]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Black ethnicity</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9865]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Smoking.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9866]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>alcohol </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9867]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>caffeine&gt;200mg/day </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9868]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Risk factor of Sporadic miscarriages:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9869]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Caffeine / Tea, mostly in first trimester.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9870]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Alcohol.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9871]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Obesity.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9872]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Age.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9873]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Environmental Factors.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9874]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anesthetic Gases – under Reas</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>aerch, confliciting</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> data.</span></p>
