INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-001-0', 't-mm-08-001', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-001" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10886]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><u><strong>1. </strong></u></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><u><strong>β</strong></u></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><u><strong>– THALASSEMIA</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10887]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>70,000 – affected worldwide.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10888]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>100 million – carrier worldwide.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10889]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1000 in UK are affected.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10890]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Thalassemia </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Major requiring</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>: </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10891]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>requiring</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &gt; 7</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> transfusions</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/year.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10892]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Thalassemia </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Intermedia</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10893]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>7 or less/ or no </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>of transfusions</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10894]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Thalassemia</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> is </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Diagnosed @ 2 – 7years.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10895]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Growth &amp; development Abnormalities without T</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ransfusion</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10896]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Corner stone of management =&gt; blood t</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ransfusion</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and chelation therapy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10897]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Complications of Iron overloa</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>d:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10898]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Subfertility – </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>hypogonadotropic</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> hypogonadism.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10899]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypothyroidism.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10900]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>DM – damage to islet cells of pancreas</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10901]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cardiomyopathy – cardiac failure 50% cause of death.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10902]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Liver damage.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10903]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Osteoporosis (ca</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>+</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> chelation with chelating agents).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10904]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Pre conception counselling:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10905]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>High dose folic Acid (all women).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10906]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Adequate chelation prior to O</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>vulation induction</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>or</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> conception.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10907]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>All hormonal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>contraception</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – safe.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10908]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>MDT:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10909]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Obstetrician – all women.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10910]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cardiologist – if cardiac problem.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10911]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hematologist – all women.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10912]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Diabetologist if DM.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10913]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Infertility specialist.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10914]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>endocrinologist – if endocrinopathy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10915]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>O</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>I </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>with</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> Gonadotrophins</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – if infertility – success of OI</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> is more</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> with </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>good</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> chelation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10916]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Optimum Glycem</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>ic control</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – fructosamin</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &lt;300nml/l – </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>at least</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 3m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>prior</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to conception.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10917]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fructosamine </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>300nml</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/l</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> = HbA1C 43mmol/mol.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10918]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Optimiz</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>e</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> TFT’S</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – (if hypo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>thyroidism</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>).</span></p>
