INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-003-1', 't-mm-08-003', 'document_html', '<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11362]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Agent of choice.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11363]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk of bleeding &lt; 2%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11364]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dose according to recent weight.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11365]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No platelet monitoring as minimal risk of H</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>I</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>T.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11366]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No anti X – a </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>monitoring </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>required.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11367]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Safe in B.F.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11368]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Decrease </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>  Dose in renal impairment.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11369]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Creatinine</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> clearance</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> - &lt;30ml / min.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11370]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Enoxa / delta &lt; 30 ml / min.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>     </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Low dose should</span></p>
