INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-004-0', 't-mm-08-004', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-004" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11419]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>4. VTE IN PREGNANCY &amp; PUERPERIUM</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11420]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Suspected PE</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> (pulmonary embolism)</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11421]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Clinical assessment.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11422]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Perform CXR, ECG.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11423]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CBC, LFT’S, RFTS.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11424]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Start LMWH (unless C/I).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11425]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>In suspected PE =&gt; look for</span></p>
