INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-009-0', 't-mm-08-009', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-009" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12048]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>LOW DOSE ASPIRIN + CALCIUM SUPPLEMENTATION FOR PREVENTION OF PRE – ECLAMPSIA:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12049]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pre – Eclampsia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> = 3 – 5%, 50,000 deaths/ year in</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> the</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> world.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12050]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Impaired placentation 8 – 18 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12051]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Screening for </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Pre – Eclampsia</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12052]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>* History:</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> </strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><em><strong>with 10% false positive detection</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12053]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pre – Eclampsia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> detection 47%.</span><span class="mm-tab" aria-hidden="true">	</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12054]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Gest Hypertension detection = 35%</span></p>
