INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-013-0', 't-mm-08-013', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-013" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12392]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>FIBRINOGEN DISORDERS</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12393]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>fibrinogenemia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – recessive, 1/ 1000,000.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12394]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>fibrinogenemia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – partial Qualitative/ quantitative, autosomal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>dominant</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12395]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dys fibrinogen – Qualitative, dominant.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12396]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Risks: </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12397]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Afibrinogenemia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> –</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>risk </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>of ICH</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, PPH.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12398]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypofibrinogenemia-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> dysfunction</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> of coagulation</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – thrombosis and pregnancy loss.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12399]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Af</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>ibrinogen</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>emia</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>: </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12400]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If fibrinogen &lt; 0.3g/lit =&gt; prophylaxis with fibrinogen concentrate 50 – 100mg/kg – Twice/weeks, throughout</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> the</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pregnancy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12401]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Target in pregnancy – 1g / lit</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12402]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Labor + P/P = 1.5/lit for 3 days Post delivery.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12403]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tranexamic acid in case of minor bleeding</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12404]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Hypo</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>fibrinogenemia:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12405]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><em><strong>         </strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><em><strong> </strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Expectant Management.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12406]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Regional an</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>aes</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>thesia:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12407]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>NSAID, I/M injections</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12408]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>E</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CV</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, mid</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cavity forceps, FBS.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>AVOID</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12409]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ventose FSE.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12410]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Regional Anaesthesia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12411]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fibrinogen replacement therapy is associated with thrombosis, so care is needed.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12412]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12413]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12414]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12415]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12416]"> </p>', 0);

