INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-017-0', 't-mm-08-017', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-017" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12641]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong> </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>SLE IN PREGNANCY</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12642]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>25% among Monozygotic twins.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12643]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Women: Man, 10: 1</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12644]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4/11 criteria for diagnosis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12645]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Pregnancy counselling:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12646]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fertility reduction in SLE is rare except:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12647]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ovarian failure due to cyclophosphamide.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12648]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>End stage renal disease.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12649]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>NSAIDS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12650]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Assessment of </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>disease </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Activity.</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12651]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>CVS =</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pul</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>monary</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> HTN, VHD, Cardiomyopathy by Echo.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12652]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Resp</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>iratory</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> =</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Pul</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>monary</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> fibrosis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> by</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> X – RAY, CT, lung function test.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12653]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Renal =</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> urine dipstick, protein: Creatinine ratio haematuria, HTN, RFT’s.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12654]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>H</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>a</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>ematological =</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> thrombo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cytopenia by </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FBC.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12655]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Immunological =</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> APLA screening, Anti ds DNA, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>anti-Ro</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/La Ab, complement C</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>3</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/C</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>4</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> levels.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12656]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>APLA =</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 30% pts of SLE are APLA +ve.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12657]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Avoid conception:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12658]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>Active disease.</u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12659]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>Pul</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>monary</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u> HTN</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, 40% mortality, 4.2% incidence among SLE, most cases are mild &lt; 40 mmHg pressure.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12660]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>TOP</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>: </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Indications</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12661]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Uncontrolled HTN</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>Despite optimal</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12662]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Worsening RFT’S</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>Pharmacological </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>Treatment</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12663]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>O</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>bstetric</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> Management:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12664]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Positive Anti RO/LA, APLA =&gt; high risk – MDT.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12665]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Stable disease = 4 weekly review of disease activity and regular assessment of fetal Growth, B.P, proteinuria.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12666]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anti RO/LA =&gt; Cardiac assessment @ 18 – 20 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12667]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fetal Echo in +ve anti RO/LA antibodies.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12668]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>@ 18 – 20 weeks </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>and then</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> FHR </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>monitoring.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12669]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12670]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Features</strong></u></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>pregnancy – related</strong></u></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>lupus activity</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[12671]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Anemia</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>- physiological</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>anemia of </span></p>
