INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-023-0', 't-mm-08-023', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-023" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13204]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong> </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>DIABETES IN PREGNANCY</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13205]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Pre conception counselling:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13206]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Individualized </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>dietary</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> advice.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13207]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Weight reduction if BMI &gt;27.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13208]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Folic acid 5mg till 12 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13209]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Monthly HbA</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>C:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13210]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Aim &lt; 48 mol/ mol – 6.5%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13211]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>C/I to pregnancy &gt; 86mol/mol – 10%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13212]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Stop other mediation pre – conceptionally.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13213]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Retinal assessment (if not done within 6m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13214]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Renal assessment (if not done within 6m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13215]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13216]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Referral to nephrologist:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13217]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>S</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>erum Creatinine</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &gt; 1.2.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13218]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Albumin: Crea</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tinine</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt; 30 mg/nmol.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13219]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GFR &lt; 45ml/min.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13220]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Gest</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>ational</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> Diabetes:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13221]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>R.F:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13222]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>BMI &gt; 30 screening @ 24 – 28 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13223]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Previous baby wight &gt; 4.5k screening @ 24 – 28 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13224]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Previous GDM @ booking if normal then Repeat @ 24 – 28 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13225]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Family history screening @ 24 – 28 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13226]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ethnicity screening @ 24 – 28 weeks.</span></p>
