INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-024-0', 't-mm-08-024', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-024" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13445]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong> </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>DKA IN PREGNANCY</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13446]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>precipitating</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> factors:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13447]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vomiting.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13448]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Infections.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13449]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Insulin non-compliance.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13450]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Insulin pump failure.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13451]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>S/S:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13452]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Abd</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ominal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Pain.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13453]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vomiting.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13454]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Polyuria, polydipsia.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13455]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Blurred vision.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13456]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Muscle weakness.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13457]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Lethargy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13458]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>drowsiness, irritability</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13459]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tachycardia, tachypnea.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13460]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypotension, shock, coma.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13461]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Biscarb =&gt;</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> harmful to mother and baby – worsen hypokalemia inhibit hyper ventilation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13462]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Investigations:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13463]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>BSL &gt; 11mnol.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13464]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ketones:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13465]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Blood &gt;3 m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>l/lit</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13466]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Urinary 2 +</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Diagnostic</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13467]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bicarb &lt; 1.5.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>criteria.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13468]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Or PH &lt; 7.3.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13469]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anion gap &gt; 12.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13470]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Base deficient </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>&gt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 4.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13471]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>S/K</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13472]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Management:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13473]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>MDT approach:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13474]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>I/V Fluids.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13475]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>I/V insulin.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13476]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Electrolyte correction</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13477]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bicarb administration of evaluation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13478]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Treatment of underlying cause.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13479]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fetomaternal monitoring + response</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> of treatment</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13480]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>I/V fluids:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13481]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>0.9% N/S 10 – 15ml/kg/</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>hr.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> then titrate according to haemodynamic status.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13482]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>70 kg women:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13483]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1 lit/hr in 1hr</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13484]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>500ml/hr in</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> next</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 4 hrs</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13485]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>250/hr in </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>next </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>8 hrs</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13486]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>150/hr onwards</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13487]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>K</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup><u><strong>+</strong></u></sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> Replacement and Insulin:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13488]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13489]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>According</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> to K</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup><u><strong>+ </strong></u></sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>levels</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13490]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13491]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&lt;3.3</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&lt;3.5 – 5.5</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt;5.5</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13492]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13493]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- Give K</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>+</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>K</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>+ </sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>+ insulin</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>give I/V insulin</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13494]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- Don’t give</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13495]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Insulin</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13496]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13497]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>K</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>+</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> replacement</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ensure</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>I/V insulin</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13498]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Adequate UOP </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>insulin infusion</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13499]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>0.5ml/ kg/ hour.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>@ 0.1 unit/kg/hr.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13500]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13501]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13502]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>40m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ol/ lit of ongoing</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>stop after DKA </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13503]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fluids.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>reversal and after </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13504]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&lt; 3.5 =&gt; consider </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>30-60min </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>of</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13505]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Medical review.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> dose of S/C </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>rapid acting </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>insulin given</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>with </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>meal.</span></p>
