INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-025-0', 't-mm-08-025', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-025" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13541]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 12pt''><strong> </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 12pt''><strong>OBESITY IN PREGNANCY</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13542]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>21% pregnant population is obese</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13543]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>47% have </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>normal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>BMI.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13544]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Maternal Risk:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13545]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GDM</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13546]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HTN.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13547]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>VTE.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13548]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PE.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13549]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Labor:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13550]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IOL.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13551]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dysfunctional labour</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13552]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Prolonged labour</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13553]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>C/S.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13554]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anesthetic</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> complication.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13555]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Maternal mortality and morbidity</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> (</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>30% obese</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>22% over weight</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13556]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Fetal:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13557]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Miscarriages</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13558]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anomalies (obese + GDM 3x anomalies).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13559]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Macrosomia.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>BMI Classification:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13560]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Still birth.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. Underweight &lt;18.5</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13561]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pre – maturity.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2. Normal 18.5-24.9</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13562]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Neonatal death.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3. Overweight </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>&gt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 25</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13563]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4. Pre-obese 25-29.9</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13564]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5. Class I 30-34.9</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13565]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6. Class II 35-39.9</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13566]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>7. Class III 40 and above.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13567]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Pre – pregnancy:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13568]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Weight reduction</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> if BMI </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>is &gt;</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>30.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13569]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Weight </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>reduces (</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1) still birth (2), </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HTN (</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3), macrosomia.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13570]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>VBAC success</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13571]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5mg FA </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1-month</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pre – pregnancy if BMI &gt; 30.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13572]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vitamin D, 10ug (1000</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IU) daily</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13573]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>ANC:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13574]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>MDT</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13575]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Consultant led BMI&gt;35.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13576]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Facilities and equipment BMI &gt;30.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13577]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Assessment of BMI @ booking then 3</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>rd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to make appropriate plan for equipment and personal required during labour and birth.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13578]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Weight gain – no consensus.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13579]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Diet</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ary</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> advice by trained professional.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13580]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anti – obesity drugs.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13581]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Orlistat – congenital anomalies.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13582]"><span class="mm-run" style=''color: ##000000; font-family: "Calibri", sans-serif; font-size: 11pt''>                                                             </span><span class="mm-run" style=''color: ##000000; font-family: "Calibri", sans-serif; font-size: 11pt''>Suppress</span><span class="mm-run" style=''color: ##FF0000; font-family: "Calibri", sans-serif; font-size: 11pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13583]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Topiramate – oral cleft.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##FF0000; font-family: "Calibri", sans-serif; font-size: 12pt''>      </span><span class="mm-run" style=''color: ##000000; font-family: "Calibri", sans-serif; font-size: 12pt''>appetite</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13584]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Phentermine </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>– oral cleft</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13585]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Lorcaserin</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> HT2C</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##000000; font-family: "Calibri", sans-serif; font-size: 12pt''>promote satiety.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13586]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anesthetic</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> assessment by obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tetric</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> anesthetist if BMI &gt; 40.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13587]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pressure sore BMI &gt;40.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13588]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>BMI &amp; THEIR IMPLICATIONS:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13589]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>BMI 40 &amp; More:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13590]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anaesthesia evaluation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13591]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Uterine rupture.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13592]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pressure sores.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13593]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>I/V line in labour.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13594]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Higher loss rate with </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>amniocentesis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13595]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>BMI 35 &amp; Above:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13596]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HTN, pre-eclampsia.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13597]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Difficult to measure SFH.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13598]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Post-dated.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13599]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Still birth.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13600]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Consultant led care.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13601]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>BMI 30 &amp; Above:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13602]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GDM screening.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13603]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>VTE, risk assessment/ scoring.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13604]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mental health screening.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13605]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Wound infection.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13606]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pre – pregnancy counselling.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13607]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Folic acid.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13608]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vitamin D levels.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13609]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Lactation advice.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13610]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>GDM</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Screening BMI </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>&gt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 30.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13611]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>HTN Screening:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13612]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Proper sized cuff.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13613]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Std – 12 x 23</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cms</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13614]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Large – 15 x 33.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13615]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Thigh – 18 x 30.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13616]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>B.P @ all visits.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13617]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>P.E more in class II.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13618]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>BMI </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>&gt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 35 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>asp</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>irin</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 150mg from 12 weeks till birth + 1 another moderate risk factor.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13619]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Mental health screening:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13620]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>BMI </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>&gt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 30 Risk – so do screening of mental health in antenatal period</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13621]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>A/N depression:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13622]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Obese – 33%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13623]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Over weight – 28%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13624]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>(N) weight – 22%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13625]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>P/N depression:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13626]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Obese – 13%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13627]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Over weight – 11%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13628]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>(N) weight – 9%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13629]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Chromosomal screening:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13630]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>TVS for NT (if difficult TAS) </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13631]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>NiPT non – specific.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13632]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Invasive procedure doesn’t    risk of miscarriages in BMI 30 – 40 </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13633]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Loss rate in BMI &gt; 48%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13634]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Structural Screening:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13635]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Difficult in obese</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13636]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Fetal monitoring:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13637]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>SFH – after 24 hours to assess growth routinely.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13638]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>SFH – difficult after BMI 35 so assess by USG.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13639]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>USG for fetal presentation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13640]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FHR by pinard stethoscope/ Doppler USG.</span></p>
