INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-027-0', 't-mm-08-027', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-027" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13872]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong> </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>LIVER MASSES IN PREGNANCY</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13873]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Liver </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Imaging in pregnancy</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13874]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Contrast enhanced MRI.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13875]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>USG:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13876]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Contrast enhanced </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>ultrasound (</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>CEUS) using </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>microbubbles</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> contrast agents</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> – safe.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13877]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CT can be done</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13878]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Nuclear medicine scan Tech 99m RBC 100% specific.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13879]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tumor makers non – specific.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13880]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Biopsy – definitive – avoided in pregnancy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13881]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Hepatic </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Hema</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>n</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>gioma</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>: </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13882]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Well </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>circumscribed</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13883]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Up to 20cm.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13884]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Size     in pregnancy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13885]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Benign 2 – 20%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13886]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Asymptomatic &lt; 5cm.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13887]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt; 10cm symptomatic + rapidly increasing.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13888]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>haemorrhage</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> if size &gt;10 cm.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13889]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Treatment:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13890]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Surgical excision/ radiological embolization after pregnancy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13891]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Focal</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> nodular Hyperplasia:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13892]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3%, benign.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13893]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Nodule </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>present in </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>78%,</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13894]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 84% has dia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>meter</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &gt; 5cm.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13895]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Central stellate Scar radiating </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>peripherally</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13896]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Well circumscribed – pseudo capsule.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13897]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Size </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>increase in</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pregnancy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13898]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Surgical resection.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13899]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Hepatic Adenomas</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> rare, occurs in women with COC</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> use.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13900]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Highly vascular lesions revealed by CT and MRI</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13901]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13902]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Lesion:</strong></u></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13903]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Solitary 32%</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13904]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Multiple 45%</span><span class="mm-tab" aria-hidden="true">	</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13905]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Adenomatosis 23%</span><span class="mm-tab" aria-hidden="true">	</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13906]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Postpartum:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13907]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Hormone</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> levels decrease leading to</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>loss of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>blood supply </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>and</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> degenerative</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>changes </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>and</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Risk of Haemorrhage</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13908]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Complications:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13909]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>catastrophic Hge</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 27.2% lifetime.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13910]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rupture</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – 15.8% - highest in 3</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>rd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, maternal Mortality 44%, fetal 38%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13911]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Treatment:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13912]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Embolization in emergency.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13913]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Surgical resection &gt; 5cm in non – pregnant stage.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13914]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>HCC:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13915]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rising in Asia due to rising He</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>p</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> B or C.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13916]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>α</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FP &gt; 1000mg/mol</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13917]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>aggressive.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13918]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cause infertility.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13919]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Acute Hge in pregnancy:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13920]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Embolization (if diagnosed before surgery).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13921]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Liver packing, intra-operatively.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13922]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13923]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13924]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13925]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13926]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13927]"> </p>', 0);

