INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-028-0', 't-mm-08-028', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-028" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13928]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>2</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>8</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>. ACUTE KIDNEY INJURY IN PREGNANCY</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13929]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1.4% of obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tetric</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> admission.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13930]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>G</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>F</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>R – Not </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>reliable</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13931]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Serum creatinine </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>decreases</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in pregnancy by 35 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>µ</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mol/l.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13932]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Average = 53 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>µ</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mol /l.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13933]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Abnormal &gt;90 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>µ</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mol/l =&gt; investigate.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13934]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>40% AKI – unrecognized.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13935]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Most common ca</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>u</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>se = Pre-eclampsia.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13936]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Management:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13937]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fluid status Assessment.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13938]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Medication review.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13939]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fluid replacement.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13940]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Diagnostic work – up.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13941]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Involvement of nephrologist if initial management is failed.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13942]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Drug dosage Adjustment:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13943]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Antibiotics.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13944]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Anticoagulants.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13945]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Insulin.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13946]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Opiates.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13947]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If GFR &lt; 30.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13948]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>NSAIDS =&gt; C/I in:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13949]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>AKI.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13950]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CKD.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13951]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>T</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>E.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13952]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Volume depletion.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13953]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Asthma.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13954]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Urea – teratogenic &gt;17mmol/l =&gt; despite medical treatment need Renal replacement therapy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13955]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Pre – Eclampsia</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13956]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Leads to AKI in 1.5 – 2% cases.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13957]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Biopsy shows:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13958]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Endotheliosis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13959]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Mgso4: </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13960]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Renal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>execration</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13961]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>U</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>rine output</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &lt;20ml/h</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ou</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>r or </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>creatinine</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &gt;90</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> then</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13962]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Give only </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>50% dose of Mgso4.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13963]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mgso4 level monitoring 4 – 6 hourly.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13964]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Maintain levels 2 – 3.5mol/lit.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13965]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Post-partum diuresis (normal).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13966]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>36 – 48 hours.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13967]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Before diuresis, oliguria is normal.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13968]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>40ml/4 hours (N).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13969]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>In immediate PP Period.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13970]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>HELLP:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13971]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cause AKI – 3 – 15%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13972]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Postpartum all parameters </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>deteriorate</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> for 48 hours.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13973]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Then recover</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13974]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13975]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13976]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If don’t recover after 48 hours &amp; AKI predominate </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>along with platelets</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> consumption.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13977]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13978]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13979]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Consider TTP.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13980]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Biopsy:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13981]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Endotheliosis + Thrombotic </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>microangiopathy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13982]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[13983]"> </p>
