INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-031-0', 't-mm-08-031', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-031" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14251]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>3</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>1</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>. CYSTIC FIBROSIS</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14252]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>8000 affected in UK, 1/25 Carrier.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14253]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Autosomal recessive, chromosome (7).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14254]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Affects:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14255]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Respiratory</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> System:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14256]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Repeated infection:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14257]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pseudomonas aeruginosa.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14258]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Staph Aureus</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14259]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Burkholderia capacia.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14260]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Long function.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14261]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pulmonary HTN.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14262]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cor pulmonale.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14263]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Respiratory failure =&gt; Death.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14264]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Reproductive system:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14265]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>C</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ervical </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mucous thickening.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14266]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Male infertility.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14267]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Delayed </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>menarche</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and oligomenorrhea (due to   BMI).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14268]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Hepatobiliary:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14269]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Liver disease – gall stones.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14270]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Pancreatic:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14271]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Weight gain    BMI.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14272]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>DM</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14273]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Due to pancreatic insufficiency.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14274]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Effects of CF on pregnancy:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14275]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Live birth 70 – 90%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14276]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>LBW.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14277]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>      </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pre – maturity 25%:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14278]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Spontaneous </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>with reduced</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> lung function.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14279]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Iatrogenic.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14280]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Poor wait gain.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14281]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Instrumental Delivery 40%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14282]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Complications associated with DM.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14283]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14284]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14285]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Pre – Pregnancy:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14286]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Counselling:</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> explain</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14287]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Risks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14288]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Leaving child alone in case of maternal death.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14289]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Assessment:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14290]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Lung function.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14291]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Glycemia control.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14292]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>BMI.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14293]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Partner Screening:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14294]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Negative – Go for pregnancy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14295]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Positive:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14296]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PGD.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14297]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Prenatal diagnosis CVS.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14298]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>ANC:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14299]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>MDT:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14300]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CF physician + nurse.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14301]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tetrician</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> + midwife.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14302]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dietitian.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14303]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Diabetologist.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14304]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anaesthetist.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14305]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Physiotherapist</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14306]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>OGTT:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14307]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>1</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14308]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>24 – 28 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14309]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>USG:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14310]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Dating.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14311]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Anomaly.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14312]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Growth.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14313]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Nutritional status + weight.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14314]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Lung function monitoring.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14315]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Individualized Birth Plan.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14316]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Effects on Pregnancy of CF:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14317]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Survival not affected.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14318]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Survival is shortened in those who are already compromised (FEV</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>1</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &lt;40%).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14319]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14320]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>C/I to Pregnancy:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14321]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FEV</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>1</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14322]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>&lt; 50%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14323]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Unstable lung function.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14324]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pul</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>monary</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> HTN:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14325]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cor pulmonale.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14326]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>B. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Capacia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> infection.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14327]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Post organ transplantation (2 – 3 years).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14328]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14329]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14330]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Graft rejection and PTB.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14331]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Delivery:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tetric</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> indications.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14332]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>An</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>a</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>esthesia:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> epidural, shorten 2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>nd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> stage.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14333]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>PNC:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14334]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>B.F exhausting.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14335]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Not go for exclusive feeding.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14336]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14337]"> </p>
