INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-035-0', 't-mm-08-035', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-035" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14691]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 12pt''><strong>3</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 12pt''><strong>5</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 12pt''><strong>. SURGICAL CAUSES OF ACUTE ABD</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 12pt''><strong>OMINAL</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 12pt''><strong> PAIN IN PREGNANCY:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14692]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1 in 500 – 635 pregnancies.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14693]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Early senior surgeon opinion should be sought.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14694]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>D/D of ab</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>dominal</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> pain in Pregnancy:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14695]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tetric</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> causes.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14696]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Surgical.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14697]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Non-surgical.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14698]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14699]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Obs</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>tetric</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong> causes</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14700]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14701]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Early:</strong></u></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>late:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14702]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Miscarriage.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>i. Abruption</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14703]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ectopic </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ii. Labour.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14704]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Urinary retention.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>iii. Rupture.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14705]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fibroids degeneration. iv. AFLP/PE</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14706]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Round ligaments pain.  v. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Chorioamnionitis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14707]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>vi. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Symphysis pubis dysfunction.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14708]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>vii. Fibroid degeneration.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14709]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>viii. Braxton hicks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14710]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Surgical:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14711]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Appendicitis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14712]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cholecystitis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Biliary colic.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14713]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>pancreatitis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14714]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Peptic ulcer.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14715]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bowel obs.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14716]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ureteric obs.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14717]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Aneurysm rupture.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14718]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Non – Surgical:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14719]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pyelonephritis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14720]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IBD</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14721]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ovarian</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cyst accident.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14722]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Constipation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14723]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pneumonia.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14724]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Psychogenic.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14725]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Trauma – abuse.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14726]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>MI.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14727]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>DKA.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##EE0000; font-family: "Calibri", sans-serif; font-size: 12pt''>Rare.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14728]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Prophylaxis </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14729]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>History:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14730]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Evaluation of presenting symptoms.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14731]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Past obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tetric</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, medical, surgical history.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14732]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Don’t forget to inquire about trauma, Abuse</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14733]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Characteristics of Pain:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14734]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Site:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14735]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Focal, sharp, finger, pointing =&gt; peritoneal pain.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14736]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Poorly localized/ segmented =&gt; visceral.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14737]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Foregut – upper abdominal pain.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14738]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mid gut – around umbilicus.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14739]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hind gut – lower abdominal pain</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14740]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Shoulder tip – haemoperiton</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>um/ visceral leakage.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14741]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Quality of Pain:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14742]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Colicky – Obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>truction</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> of hollow viscus ureter, biliary </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>duct</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14743]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Burning – </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14744]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Peptic ulcer.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14745]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Esophageal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14746]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pancreatitis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14747]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Constant – peritoneal inflammation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14748]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Duration and Timing:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14749]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Exacerbating &amp; Reliving Factors</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14750]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Visceral pain – restlessness</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14751]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Perinatal injury/ irritation – exaggerate with pain</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14752]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Associated symptoms:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14753]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Examination</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>:</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> General + abdominal</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14754]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Physiological changes</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14755]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Blood volume = 40%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14756]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Co = 10 – 30%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14757]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HR – from 70 = 80-90bpm</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14758]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>O</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> consumption = 20%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14759]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Temperature</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14760]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tidal volume 500 – 700ml</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14761]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Anatomical changes:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14762]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Gravid uterus</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14763]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Shift appendix in upper Quadrant </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14764]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hamper free fluid</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14765]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Difficulty in assessing site of tenderness</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14766]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14767]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Let women on her site</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14768]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14769]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Then check tenderness, if remain same then non uterine</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14770]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Difficulty assessing mass</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14771]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14772]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Turn on side then palpate</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14773]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Hydroureters</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – 2cm</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14774]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Hydronephrosis</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14775]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Right - &gt;15mm</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14776]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Left - &gt;5m</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14777]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>(</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>pelvicalyceal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> diameter)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14778]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Clinical Red Flags:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14779]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Readmission</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14780]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Repeated doses of opiates given for analgesia without a ca</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>u</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>se of pain being established</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14781]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>New onset anxiety &amp; confusion being </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>attributed</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>psychiatric</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> rather than underlying organic cause</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14782]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Investigation:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14783]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Bed side</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14784]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pulse, B.P, RR, Temp, O</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> sat</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14785]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Urine dip</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14786]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt; 1+ protein urea =&gt; Qua</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>nt</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ification</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14787]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ECG – epigastric/ upper abdominal pain + risk factor for MI</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14788]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Biochemical</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14789]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FBC – TLC normal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>up to</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> (5.9 – 15.6 x 10</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>9</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14790]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CRP – (N – 20mg/dl)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14791]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Creatinine</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>up to</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 0.8</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14792]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ABGS – physiological hyperventilation   PO</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>,  </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> PCO</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>,   HCO</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>3</sub></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14793]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Lactate </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>for </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tissue perfusion.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14794]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Imaging:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14795]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>USG – 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> line for appendicitis:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14796]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>90% </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>inconclusive</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14797]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sensitivity 60%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14798]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Spec</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ificity</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – 100%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14799]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>X – ray </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>erect abdomen - </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> CXR with shield is safe.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14800]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dose up to 10m GY is negligible in 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, risk of childhood ca</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>nc</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>er 0.002%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14801]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>MRI safe</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14802]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CT – avoid – childhood CA 0.1 – 0.3%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14803]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Management MDT input:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14804]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>OBS consideration:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14805]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Miscarriage risk 0.7%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14806]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PTB 3.2%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14807]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Laparo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>scopy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> more risk of miscarriage but equal risk of PTB.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14808]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>After 20 weeks – left lateral tilt during surgery.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14809]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Steroid 24 – 34 + 6 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14810]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fetal monitoring:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14811]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Early – Auscult</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14812]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Late – CTG.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14813]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>VTE prophylaxis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14814]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anti D – whenever uterine manipulation done.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14815]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Surgical consideration:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14816]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>MDT.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14817]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Incisions </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>according</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to pregnancy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> duration</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &amp; surgical condition </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14818]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Appendix</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> shifting upward as pregnancy advances.</span></p>', 0);

