INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-036-0', 't-mm-08-036', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-036" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14819]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>3</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>5</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>.1. A – APPENDICITIS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14820]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1/800.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14821]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Commonest cause of acute abd</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>omen</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in pregnancy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14822]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>S/S:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14823]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Non – Classical.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14824]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rt lower Q pain 75% (non-pregnant 95%).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14825]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Upper Q pain.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14826]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>N/V, anorexia, dysuria</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>. </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14827]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rebound </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tenderness</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> (</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>roving</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> sign).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14828]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Abd</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ominal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> guarding.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14829]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rectal tenderness.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14830]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fever 39.3</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>C.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14831]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tenderness / pain in Mc – </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Burn</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ey</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>’</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>s</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> point (6cm from anterior</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> sup</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>erior iliac</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> spine).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14832]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>D/D:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14833]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ectopic.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14834]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Threated miscarriage.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14835]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>G.E.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14836]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Musculoskeletal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pain.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14837]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pyelonephritis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14838]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>T</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>E, HELLP.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14839]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Abruption.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14840]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Chorioamni</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oni</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14841]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ovarian thrombophlebitis (post-natal).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14842]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Investigations:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14843]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Leukocytosis – Non-specific.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14844]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CRP – non-specific.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14845]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Imaging:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14846]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Purpose is:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14847]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>To chance of</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> negative appendectomy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14848]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>To reduce delay in surgery.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14849]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>USG:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14850]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>SEN 67 – 100%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14851]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Spec 83 – 96%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14852]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>MRI:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14853]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sen 86%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14854]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Spec </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>97%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14855]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Management:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14856]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Perfora</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>ted Appendix:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14857]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Laparotomy + appendectomy + lavage + ICU Admission + delivery of baby </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>by C/S </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>(delivery improve outcome).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14858]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Acute Appendicitis appendectomy:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14859]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Incision</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14860]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Midline – when diagnosis is not clear or delivery of.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14861]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Transverse on max tenderness area.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14862]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Risks of Appendicitis:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14863]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fetal loss rate </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14864]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>simple appendix 1.5%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14865]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>peritonitis = 6%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14866]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Perforated appendix 36%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14867]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Adhesions – subfertility.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14868]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PTB – infected appendix </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>irritates</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> uterus.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14869]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Laparoscopy in all </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14870]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk of fetal loss but same PTB rate.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14871]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>I/O normal looking appendix =&gt; Remove as it is histological </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>diagnosis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14872]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Chronic appendicitis:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14873]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Walled off appendix, appendicular mass.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14874]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Conservative treatment. [no surgery]</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14875]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Anesthesia management/ Pre –op/ Surgical Management:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14876]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GA riskier, regional is preferred.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14877]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tocolysis NR (GA has oncolytic effect).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14878]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Steroid</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> @</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 24 – 34 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14879]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CTG during</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> late </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14880]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FHR auscultation during</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Early </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14881]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Abnormal FHR:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14882]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Correct hypovolemia.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Not corrected</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14883]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Correct hypotension.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>with conservative</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14884]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ensure </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>left</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> lateral tilt.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>treatment =&gt; C/S</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14885]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Oxygenation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14886]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Analgesia:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14887]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Opiates safe</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14888]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>NSAIDS up to 32 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14889]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>VTE prophylaxis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> during admission ace to GTG.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14890]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A/B given as per protocol</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14891]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Anti D when there is uterine manipulation.</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14892]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Minimal uterine &amp; cx manipulation</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> intraoperatively</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>.</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14893]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Simultaneous C/S:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14894]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Perforated appendix/ Maternal sepsis requiring maternal resuscitation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14895]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt; 37 + obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tetric</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> indication.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14896]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Not done routinely.</span></p>', 0);

DELETE FROM content_blocks WHERE topic_id = 't-mm-08-037';
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-037-0', 't-mm-08-037', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-037" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14897]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>3</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>5</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>.2. B – BILIARY COLIC/ CHOLECYSTITIS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14898]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1 – 6/1000.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14899]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>90% due to gall stones.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14900]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>nd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> most common (mor</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e in pregnancy due to   </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cholester</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ol</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> sec</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>retion + super saturation of of bi</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>le).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14901]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Late Gestations – appendicitis and chole</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cystitis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> similar presentation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14902]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>LFTS to rule out obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tructive</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> jaundice.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14903]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>USG 95% Sens</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>itive</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14904]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Management Biliary colic:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14905]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Adequate analgesia, anti-emetics.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14906]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Lap chole after resolution of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>acute</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> episode.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14907]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Stone in CBD:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14908]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ERCP for diagnosis and treatment.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14909]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Acute </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>cholecystitis</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14910]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>N</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PO and antibiotics</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14911]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fluids I/V.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14912]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Definitive cholecystectomy after acute resolution.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14913]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Perforation, focal/ </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>generalized</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> peritonitis =&gt; urgent surgery.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14914]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Readmission without surgery = 4.7 times.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14915]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Readmission with surgery = 0.4 times than (N).</span></p>', 0);

