INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-038-0', 't-mm-08-038', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-038" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14916]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>3</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>5</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>.3. C – BOWEL OBSTRUCTION</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14917]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1/500</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14918]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Causes:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14919]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Adhesions.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14920]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bowel displacement + distortion due to Gravid uterus.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14921]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Og</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ilvie</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> syndrome =</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>pse</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>udo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-obstruction</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – functional colonic obstruction due to pregnancy/ delivery by C/S.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14922]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Diagnosis:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14923]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>S/E</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14924]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>RFTS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14925]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>X – RAY erect abd</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ominal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> [avoid] </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14926]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>USG – safe </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14927]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>MRI – safe </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14928]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Treatment:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14929]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>NPO, bowel decompression.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14930]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Senior surgeon involvement.</span></p>', 0);

