INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-039-0', 't-mm-08-039', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-039" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14931]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>3</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>5</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>.4. D – PANCREATITIS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14932]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rare 3/19000.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14933]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>70% due to gall stones.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14934]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Lipase more sensitive for diagnosis than amylase</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14935]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> surgical inputs.</span></p>', 0);

