INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-040-0', 't-mm-08-040', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-040" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14936]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>3</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>5</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>.5. E – URETERIC OBS</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>TRUCTION</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''> &amp; PYELONEPHRITIS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14937]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Complete urine examination leukocytosis, microscopic </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>hematuria</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14938]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Py</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>elonephritis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> =&gt; admission.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14939]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>I/V </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>antibiotics</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14940]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fluids.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14941]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Surgery:</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pt unwell despite treatment, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>emphysematous</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pyelo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>nephritis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or obstructing calculus.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14942]"> </p>
