INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-08-041-0', 't-mm-08-041', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-041" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14951]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>3</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>6</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>. AIR TRAVEL IN PREGNANCY</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14952]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Partial pressure of O</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> =&gt; 10%    in SPO</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in blood.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14953]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Humidity 15%    in aircraft.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14954]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Risks:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14955]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Spontaneous miscarriage.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14956]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IUD.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14957]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PTB.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14958]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>DVT (3 times prolong travel). 18% higher with each 2 hours    in flight duration.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14959]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>C/I to Commercial Air Travel:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14960]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Severe anemia &lt; 7.5gm/dl.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14961]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Recent Hge</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14962]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Otitis media and </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>sinusitis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14963]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Serious cardiac/ Resp disease.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14964]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Recent sickling crises.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14965]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Recent GI surgery including laparoscopy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14966]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fracture – during 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> few days of cast.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14967]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Practical consideration &amp; Advice:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14968]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Location of pregnancy &amp; viability before travel should be checked.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14969]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vaccination.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14970]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>antimalarials.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14971]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Avoid travel from 37 weeks in singleton and 32 weeks in twins.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14972]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Steps to avoid DVT:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14973]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Aisle seat to facilitate movements.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14974]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Regular walk.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14975]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>In seat exercise every 30 min on medium/long haul flight.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14976]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Avoid dehydration:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14977]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Fluid intake.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14978]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Avoid coffee, alcohol.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14979]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Individualized risk assessment for thrombosis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14980]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14981]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14982]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14983]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Flights:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14984]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Short – no specific measure.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14985]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Long &gt; 4 hours.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14986]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14987]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Risk assessment for DVT:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14988]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14989]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No risk</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk Factors present</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14990]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>DM</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14991]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Compression </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HTN</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14992]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Stockings</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Thrombophilia</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>   </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>LMWH on</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14993]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Nephrotic </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>   </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>the day of</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14994]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Syndrome</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>   </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>travel &amp; 7</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[14995]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Obesity</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>    </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>Days</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>after</span><span class="mm-run" style=''color: ##FF0000; font-family: "Calibri", sans-serif; font-size: 10pt''>.</span></p>
