INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-001-0', 't-mm-09-001', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-001" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15658]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>1. PERINATAL INFECTIONS:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15659]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>DNA Viruses:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>All are Double s</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>tandard</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> DNA </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>viruses </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>except PARVO virus.</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15660]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>VZV.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15661]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HSV</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15662]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HPV</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15663]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HEP B</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15664]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Adeno</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>virus</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15665]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Parvo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>virus</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15666]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>RNA viruses:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15667]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mumps</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15668]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Measure</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15669]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rubella</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15670]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Toga</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15671]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Protozoa: </strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15672]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Malaria, Toxo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>plasmosis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15673]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Spirochete:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15674]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Syphilis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15675]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Zika Virus: </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15676]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Microcep</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ha</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ly:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15677]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Contraception:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15678]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0 </sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>– Both partners are traveler.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15679]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – male partner is traveler.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15680]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – female partner is traveler.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15681]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Hep B:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15682]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>In all cases give HEP B vaccination + </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>im</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mun</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oglobulin EXCEPT</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15683]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>When e antibodies positive because risk of transmission is low just give vaccination</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> is given</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15684]"> </p>', 0);

