INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-004-0', 't-mm-09-004', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-004" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15865]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>1.3. </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>HIV IN PREGNANCY:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15866]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>MDT + Peer support.</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15867]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mental health assessment</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> @</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15868]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Booking.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15869]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4 – 6 weeks postnatal.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15870]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3 – 4m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> postnatal.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15871]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sexual health screening:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15872]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Recommended in newly diagnosed.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15873]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Suggested in previously diagnosed.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15874]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Monitoring &amp; testing:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15875]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>HIV Resistance</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – all</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pts</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> before treatment except late presenters after 28 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15876]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>CD4:</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt; 350 cells/mm</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15877]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Base line</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15878]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Delivery</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15879]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Before initiation of treatment.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15880]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Viral load:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15881]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>2 – 4 weeks after treatment commencement. </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15882]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Once in each trimester.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15883]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>@ 36 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15884]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>@ delivery.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15885]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>LFT’S:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15886]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Before CART.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15887]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>@ each routine blood test.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15888]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Persistent</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> viral road:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15889]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt; 50 HIV copies look for followings.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15890]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>concomitant medication.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15891]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Compliance.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15892]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Perform resistance testing.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15893]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Drug monitoring.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15894]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Optimize best regimen.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15895]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Consider intensification.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15896]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Women </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>conceive</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> on CART.</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15897]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Continued CART except:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15898]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Non st</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>andar</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>d regimen</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> like protease inhibitor monotherapy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15899]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Darunavir</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/ </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cobi stat</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15900]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Elvitegravir</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>            </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Low</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>pharmacokinetics </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15901]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15902]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>R</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ltegravir – in divided dosing 400 B.D instead of 1200 OD.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15903]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Dolutegravir – NTD after 8 weeks can be given.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15904]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Not on CART when to start (all women by 24 weeks).</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15905]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15906]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Viral load &gt;100,000.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>30,000 – 100,000 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>   </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>&lt;</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 300,000 </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15907]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>OR</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> CD</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>4</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &lt; 200.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15908]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15909]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>nd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> early</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>      </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>as soon as</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>     </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>possible </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>in</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15910]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>nd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15911]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>What to start?</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15912]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tenofovir DF/ abacavir </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> (</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>TA</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>)</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15913]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Emtricitabine  / lamivudine</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> (</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>EL</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15914]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Efavirenz</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> / </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>atazanavir (</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>EA</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15915]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Alternative:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15916]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rilpivirine.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15917]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Raltegravir or </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Darunavir</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15918]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15919]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Integrase inhibitor:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15920]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>With high viral load &gt; 100,000.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15921]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Where CART is failing to suppress virus.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15922]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Zidovudine:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15923]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Recommended only if:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15924]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>P</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>t</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> declines CART with viral load &lt;10,000 copies and willing for C/S.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15925]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15926]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Dosage:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15927]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Same as non-pregnant except </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Raltegravir</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15928]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15929]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>TDM:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15930]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Therapeutic drug monitoring are recommended in:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15931]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Comb</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ination</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> of tenofovir DF &amp; atazanavir.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15932]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Off license dosing.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15933]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Switching off dosing.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15934]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Late Presentation:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15935]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>In Labor</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>:(NLRZ)</strong></em></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15936]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Nevirapine stat.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15937]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Start:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15938]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Zidovudine.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15939]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Lamivudine.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15940]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Raltegravir.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15941]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>I/V:</u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15942]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Zidovudine during labor.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15943]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Till delivery.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15944]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>After 28 weeks.</strong></em></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15945]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No delay.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15946]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Viral load unknown or &gt;100,000.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15947]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15948]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15949]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4 drugs, including Raltegravir OR Dolutegravir (RD).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15950]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Pre – Term</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>:</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>(NLRZ +T)</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15951]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Add tenofovir DF</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to labour and delivery regimen</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15952]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>SROM</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15953]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Urgent HIV + </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15954]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15955]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15956]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Start treatment without confirmation</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15957]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>HIV – 2:</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Discussion with HIV 2 expert.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15958]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Protease </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>inhibitor-based</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> regimen.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15959]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>HIV &amp; Hepatitis B coinfection:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15960]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Confirmation of viremia by:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15961]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HBV – DNA e Ag.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15962]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HEP C.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15963]"><span class="mm-run" style=''color: ##EE0000; font-family: "Calibri", sans-serif; font-size: 12pt''>HEP A.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##EE0000; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>New Diagnosis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15964]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HEP D.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15965]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>LFT’S:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15966]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>LFT’S 2 – 4 weeks after CART.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15967]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Continue treatment during pregnancy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15968]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Add tenofovir DF dose.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15969]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Or with lamivudine/ </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>emtricitabine</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15970]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15971]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Hep A vaccination:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15972]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>0 – 6m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15973]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>0 – 1 – 6m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> if CD</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>4</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &lt; 300.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15974]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CART:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15975]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Continue PP.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15976]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Neonatal vaccination + HBIG:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15977]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Within 24 hours.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15978]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>SVD with fully suppressed HIV.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15979]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Irrespective of HEP B load.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15980]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>HEP C co</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>infection:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15981]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>LFT’S, HCV RNA + genotyping repeat LFT’S 2 – 4weeks after CART.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15982]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Stop treatment of HEP C in pregnancy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15983]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ribavirin based DAA</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15984]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>(directly acting antiviral).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15985]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HEP B vaccination.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15986]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HEP A vaccination.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15987]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Delivery acc to HIV - protocols</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15988]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CART after delivery continues.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15989]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>ANC of Pregnancy with HIV</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15990]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>USG as routine</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15991]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ECV</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &lt; 50 copies.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15992]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>NIPT recommended if required</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15993]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Invasive testing till viral load &lt; 50.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15994]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Not CART/ Viral load high =&gt; invasive testing required.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15995]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15996]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15997]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>R</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ltegravir.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15998]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Nevirapine single dose 2 – 4 hours before procedure.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15999]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Mode of Delivery:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>elective birth</strong></span></p>
