INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-005-0', 't-mm-09-005', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-005" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16106]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>1.4. </span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>HERPS IN PREGNANCY + NEONATAL CARE:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16107]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>50% HSV – 1.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16108]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>50% HSV – 2.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16109]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Neonatal Herpes:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16110]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Skin, eye, mouth = 30%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16111]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Local CNS = 60%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16112]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Disseminated = 70%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16113]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No miscarriage.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16114]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No teratogenicity</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16115]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16116]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16117]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><u><strong>Herpes Suspected – Refer to GUM PCR for </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><u><strong>diagnosis</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><u><strong> + contact training.</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16118]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16119]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> Acquisition in 3</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><sup>rd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> (&gt; 28 weeks) Ig – M +ve</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>St</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>andar</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>d dose treatment + suppressive therapy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Acyclovir 400mg TDS till delivery</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> for 5 days(435)</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Lidocaine 2%</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> for</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>  </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Paracetamol for pain</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Within 6 weeks’ risk of neonatal infection 41%.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>C/S</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>- Observe baby</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>- Routine care</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>[no swabs]</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Recurrent Herpes 1 – 3%.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Treatment with std dose </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>(</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>435</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>)</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> if necessary, otherwise only symptomatic treatment.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Daily suppressive acyclovir from 36 weeks 400 TDS till delivery.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Normal vaginal delivery.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Ulcers Positive</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>           a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>bsent      </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> @ time of delivery</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Observe baby for</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>routine</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> 24 hours.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>care</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Well</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>- Discharge [no SWAB].</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>- Advice parents regarding any concern.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> Herpes in 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> /2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><sup>nd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> before 28 weeks.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Treatment with st</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>andar</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>d dose  + suppressive acyclovir from 36 weeks.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>SVD</span></p>
