INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-006-0', 't-mm-09-006', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-006" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16171]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>1.5. MALARIA IN PREGNANCY</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16172]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Tertian Malaria –</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 48 hours’ cycle – P oval</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, vivax, falciparum</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16173]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Quartan</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> Malaria –</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 72 hours’ cycle – P Malariae.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16174]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Immunity lost</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> within 2 years.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16175]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Gold std</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> Test</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> microscopic examination of thick &amp; thin film.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16176]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Incidences:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16177]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>75% falciparum, 0.5 – 1% Mortality</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16178]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5.5% ovale 12.9% vivax, 2.1% Malaria</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16179]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Suspect malaria:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16180]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fe</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ver</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> + history of travel </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>to endemic area </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>or residence (&gt; 6m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16181]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Recent return 3 weeks – viral infections.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16182]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Chemoprophylaxis not 100% effective.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16183]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16184]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16185]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>S/S + investigations – Rapid Testing + blood film (1 hour).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16186]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Other Tests –</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> CBC, BSL, U/E, blood C/S, urine dip, stool, CXR, USG.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16187]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Blood film shows:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16188]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>No evidence of Malaria.</em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16189]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Falciparum.</em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16190]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Non</em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>-Falciparum</em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>.</em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16191]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>1. No evidence of Malaria:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16192]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Repeat film – (after stopping prophylaxis).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16193]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>negative </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>films 12 – 24 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>hours</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16194]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>part exclude malaria so</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> f</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>inish chemoprophylaxis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16195]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Empirical</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Treatment – Severe malaria expected.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16196]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Stop prophylaxis before repeating (as it give negative report).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16197]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>2. Non – Falciparum:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16198]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Chloroquine – 600mg stat dose</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16199]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>300mg – 6 – 8 hours later.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16200]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>300mg – D</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ay </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16201]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>300mg – D</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ay </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16202]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>To prevent relapse (vivax/ovale).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16203]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>300mg – weekly chloroquine.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16204]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>During pregnancy chloroquine resistant cases are treated by mefloquine.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16205]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>To prevent relapse </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>after delivery</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and testing for G</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PD </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>primaquine is recommended</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>. (avoid in pregnancy).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16206]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>3. Falciparum:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16207]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mixed species or not characterized.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16208]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Admit.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16209]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Assess severity.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16210]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Complicated.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16211]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Uncomplicated.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16212]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Complicated:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16213]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Admit in HDU</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16214]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt;</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2% </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>parasitized</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16215]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>50% mortality.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16216]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Antimalarial immediately.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16217]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fluid balance – </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CVP </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>line.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16218]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Monitoring.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16219]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>BSL – 1 hourly</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16220]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4 hourly</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16221]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>HR.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16222]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Temp</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16223]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>RR.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16224]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>SPo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16225]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>JVP.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16226]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Repeat daily.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16227]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CBC</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16228]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Parasite count.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16229]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>LFT, RFT, clotting screen.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16230]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Treat for G negative bacteria.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16231]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Artesunate</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> I/V 2.4mg/kg @ 0, 12, 24hours’ stat dose (drugs of choice any Gestation, then daily till patient is stable).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16232]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Quinine I/V 20mg/ kg in 5% D/W over 4 hours. Then 100mg/kg every 8 hours then oral when Pt can swallow.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16233]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Uncomplicated:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16234]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Admit in ward</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16235]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&lt;2% parasitemia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16236]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mortality 0.1%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16237]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Quinine 600mg 8 hourly + clindamycin 450mg 8 hourly (before 13 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>weeks drug</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> of choice).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16238]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>OR</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16239]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Raiment</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4-tab</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, B.D for 3days.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16240]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>OR</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16241]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Proguanil + Atovaquone (m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>alar</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>one) 4 doses daily – 3 days.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16242]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Some important points about Malaria:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16243]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Expert advice (esp</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ecially</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> recurrent &amp; severe).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16244]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rapid detection negative in low </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>parasitemia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &amp; P – vivax.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16245]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Gold std microscopy thin/thick film.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16246]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rapid detection </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>followed by</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> microscopy (Number of infected cells, species, stage).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16247]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Premunition</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>: Natural immunity acquired against malaria.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16248]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Low premunition – 90% with low premunition develop anemia.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16249]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>UK population low premonition.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16250]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Relapses –</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> due to planta sequestration:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16251]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>25 – 42 days’ average, relapse time </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16252]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>85 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>days</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> after quinine.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16253]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>98 days after </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Artesunate</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16254]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>63 days with artemether, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lumefantrine</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> </strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16255]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Weekly films –</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> reduces mortality due to recurrence.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16256]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>treatment of recurrence =&gt; </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>artesunate</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 84% success. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Artesunate</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 100mg/ day </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>for</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 7 days + clinda</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mycin</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 45mg T</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>DS</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – 7 days (WHO recommendation for relapse).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16257]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypoglycemia exacerbation by quinine =&gt; fetal distress.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16258]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Cinchonism, 7 days’ treatment:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16259]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Headache.</em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16260]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Nausea.</em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16261]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Diarrhea. </em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16262]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Vomiting.</em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16263]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Blurred vision.</em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16264]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>Auditory problems.</em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16265]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypoglycemia – due to hyper insulinemia.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16266]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>commonest S/E of quinine.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16267]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Infection control specialist</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> =&gt; recurrent/ severe cases.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16268]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Treatment of complications:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16269]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pulmonary edema – JVP aim of rt arterial pressure &lt;10cm H</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>O, (it has 50% mortality)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16270]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anemia Hb &lt;8:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16271]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Pack cell + I/V </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>frusemide</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> 20mg.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16272]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Exchange transfusion.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16273]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Secondary bacterial infection when pt become hypotensive systolic B.P &lt;80mg</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16274]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>C/S =&gt; start </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ceftriaxone</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> immediately due to risk of infection.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16275]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16276]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Thrombocytopenia:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16277]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Recovers 7 days in 90%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16278]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&amp; 100% within 14 days</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16279]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Of treatment.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16280]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Thrombocytopenia is risk</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16281]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Of   blood loss in endemic</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16282]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Areas but not PPH.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16283]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Fetal complications:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16284]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IUGR, Pre – Term, fetal distress.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16285]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>MDT – severe fetal compromise.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16286]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>(ICU specialist, infectious disease specialist, obstetrician, neonatologist).</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16287]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Aim is to prevent pre – term, IUD.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16288]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> VTE</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> Prophylaxis</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16289]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Plt &lt;100, - withhold.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16290]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Peripartum</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> Malaria:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16291]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Pla</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>ce</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>nt</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>a</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>l sequestration</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> =&gt; P Falciparum most common:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16292]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Is indication for following tests:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16293]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>placental histopathology</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16294]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cord &amp; baby blood film</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>  </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> To</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> detect</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16295]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Every week for 28 weeks.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
