INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-008-0', 't-mm-09-008', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-008" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16586]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''> </span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>C</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>YTOMEGALO</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>VIRUS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16587]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Most common congenital infection – 0.5%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16588]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>40 – 60% seropositive.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16589]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>37% Neonates born with infection.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16590]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>10% have clinical manifestation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16591]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>40% transmission in 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, 2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>nd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16592]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>80% transmission in 3</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>rd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16593]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> infection cause miscarriage.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16594]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Transmission </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>increases</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> with Gestation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16595]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Infectivity </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>decreases</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> with Gestation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16596]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Transmission by saliva, body fluids</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16597]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Screening:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16598]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Symptomatic women or USG suggestive of CMV other causes of placental insufficiency ruled out.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16599]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16600]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16601]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>=</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt; IgG</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Ig</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>M alone</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>are </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>unreliable</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>    </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16602]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>=&gt; positive IgG and </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IgM with</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> low avidity show</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>       </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>recent infection:</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 3-4 months</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16603]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>=&gt; high avidity </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>suggests</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> old infection &gt;3 months </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16604]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Assessment of fetal infection:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16605]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>USG</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16606]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>20% detection.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16607]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Unreliable, serial USG 2 – weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16608]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Amniocent</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>esis</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16609]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6 – 8 weeks after infection &amp; after 20 weeks GA.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16610]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16611]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16612]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Positive CMV</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16613]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16614]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Quantitative DNA</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16615]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>      </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Positive</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> on Amniocentesis or USG</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16616]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16617]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>counselling regarding risk of symptomatic disease.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16618]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16619]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16620]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sensorineural deafness 12%, Leading cause of non – genetic deafness.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16621]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CP – 8%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16622]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5 – 20% symptomatic infants.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16623]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Infants can have</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16624]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Jaundice, petechial rash Hepatosplenomegaly, microcephaly, SGA.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16625]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Management:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16626]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Asymptomatic fetus mild to moderate disease:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16627]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Expectant.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16628]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Detailed Examination of ear and eyes after birth and postnatal t/m and lifelong follow</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>up of affected neonat</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16629]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Examination of plac</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>enta</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16630]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Symptomatic:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16631]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mild, mod, severe disease.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16632]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Top</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16633]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Post </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>mortem</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> examination.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16634]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Examination of placenta.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16635]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>MRI </strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>+</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16636]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>B/L periventricular calcifications.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16637]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>@ 28 – 32 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16638]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Repeat 3 – 4 weeks if needed.</span></p>
