INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-011-0', 't-mm-09-011', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-011" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16790]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>RUBELLA</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16791]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Rubella</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16792]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>16/52 weeks – </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>substantial</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16793]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16794]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Top</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16795]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>16 – 20 weeks – minimal risk</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16796]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16797]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Follow up</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16798]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>After 20 weeks – no risk</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16799]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16800]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Reassure.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16801]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Congenital Rubella symptoms:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16802]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>S</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ensory neural</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> deafness.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16803]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PDA, VSD.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16804]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Eye lesions, cataract, micro </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ophthalmia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16805]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Microcephaly.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16806]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mental retardation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16807]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Implications of Rubella to Fetus/ Neonate:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16808]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>SN – deafness.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16809]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>DM.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16810]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Thyroid disease.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16811]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GH deficiency.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16812]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vascular effects </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16813]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>encephalitis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16814]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16815]"> </p>', 0);

