INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-012-0', 't-mm-09-012', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-012" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16816]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>1.11.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>SYPHILIS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16817]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>70</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> cases/ million deliveries.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16818]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Treponema pallidum.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16819]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Transmission:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16820]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Direct contact with lesion.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16821]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Vertical transmission.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16822]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Universal screening.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16823]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Course of syphilis:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16824]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Early:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16825]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> maculopapular</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> rash + regional lymphadenopathy 10 days – 3m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16826]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Chancre, anogenital region, hard – indurated.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16827]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Secondary:</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>untreated primary lesions.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16828]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>25% sec syphilis after 4 – 10 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16829]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Multisystem involvement.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16830]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rash + generalized lymphadenopathy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16831]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Latent Asymptomatic:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16832]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Early – within 2 years.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16833]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Late – after 2 years.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16834]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Late:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16835]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Tertiary, Quarterly.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16836]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Gumas, system involvement:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16837]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CVS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16838]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CNS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16839]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Tabes dorsalis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16840]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>General paresis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16841]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Diagnosis:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16842]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Best test: TPHA, EIA.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16843]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Screening: VDRL.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16844]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Microscopic identification.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16845]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>USG:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16846]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Early onset SGA:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16847]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>TORCH screening.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16848]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Karyotyping.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16849]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FGR.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16850]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Brain:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16851]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Calcification.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16852]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Hydrocephaly.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16853]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Hydro anencephaly</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16854]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Microcephaly.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16855]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>GI:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16856]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Abnormal liver, spleen, bowels.</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16857]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Ascites, hepatosplenomegaly.</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16858]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Congenital syphilis:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16859]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hydrops.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16860]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Nasal bone depressed, saddle nose.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16861]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rash.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16862]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hepatosplenomegaly.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16863]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Petechial rash.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16864]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Weinberger sign.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16865]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Neonatal:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16866]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Untreated – 50% dies.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16867]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Frontal bossing.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16868]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Saddle nose.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16869]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Interstitial keratitis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16870]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rhagades.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16871]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Perforated hard palate.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16872]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hutchinson teeth.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16873]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mulberry molar.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16874]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Saber shins.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16875]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Fetal implications:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16876]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Before 16 weeks – rare.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16877]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Miscarriage.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16878]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Still birth.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16879]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Neonatal death, disease or latent infection.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16880]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Untreated syphilis =&gt; 50% loss.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16881]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Treatment of syphilis:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16882]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Non – pregnant.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16883]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pregnant.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16884]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16885]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Non – pregnant:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16886]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Early:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16887]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Benzathine penicillin G 2.4MU I/m x Stat single dose.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16888]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16889]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Amoxicillin 2mg P/o TDS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16890]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>+ </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>probenecid</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 500mg QDS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16891]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16892]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ceftriaxone 2g I/M or I/V 10 – 14 days.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16893]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Pregnancy:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16894]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Early syphilis:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16895]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16896]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Up to 28 days.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>After 28 days.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16897]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Penicillin G 2.4MU I/m.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>double dose</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16898]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Single dose.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Day 1</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16899]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Day </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>8</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16900]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Late syphilis</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> in pregnancy</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16901]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Late latent/Gumas/CVS/CNS.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16902]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Doses</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16903]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Day 1, 8, 15.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16904]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Neurosyphilis</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16905]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Procaine</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> penicillin</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> G</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16906]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1.8 – 2.4 MU OD</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>14 days.</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16907]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Plus</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16908]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Probenecid 500mg QDS.</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16909]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Benzyl Penicillin</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16910]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>10.8 – 14.4 daily.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16911]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1.8 – 2.4 I/V every 4 hours for 14 days.</span></p>
