INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-015-0', 't-mm-09-015', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-015" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17070]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>MATERNAL SEPSIS DURING &amp; FOLLOWING PREGNANCY</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17071]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>WHO</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> definition</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> of </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Sepsis</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17072]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Organ dysfunction resulting from infection during pregnancy, child Birth, Post abortion or post-partum period.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17073]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Septic shock:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17074]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Persistent hypotension, requiring vasopressor to maintain an adequate B.P (MAP 65m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>hg or more). </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Alongside</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>n</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>     </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>increase in </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>serum lactate &gt;2m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ol despite adequate volume replacement.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17075]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Risk Factors:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17076]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Maternal:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17077]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Obesity</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17078]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Impaired glucose tolerance.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17079]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anemia.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17080]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>DM</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17081]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Age &gt; 35.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17082]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GAS in contact.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17083]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GBS carriage.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17084]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pelvic infection.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17085]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Obs</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>tetric</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Risk</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> Factors:</strong></span></p>
