INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-020-0', 't-mm-09-020', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-020" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18229]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>7. </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>PLACENTA PREVIA, ACCRETA:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18230]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Previa and anterior low lying more risk of bleeding.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18231]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Blood tx 12 times more in C/Section due to Previa than others indication.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18232]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>lacenta previa</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> 1/200 @ term</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18233]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>percreta mortality = 7%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18234]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Recurrence Previa 23/100</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18235]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Routine anomaly scan @ 18 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><sup>+6</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> – 21</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><sup>+6</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18236]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18237]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>90% low lying regress by term</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18238]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18239]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u><strong>Risk</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u><strong> Factor </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u><strong>of placenta </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u><strong>Previa:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18240]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Smoking.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18241]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>ART.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18242]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Age.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18243]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>LGA.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18244]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Twins.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18245]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Multi gravida</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18246]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>C – section.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18247]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 8pt''>Previous 1 – 4.5%, 10/1000.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18248]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 8pt''>Previous 2 – 7%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18249]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 8pt''>Previous 3 – 6.5%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18250]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 8pt''>Previous 4 – 44%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18251]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Previa Accreta</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> PAS:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18252]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Risk factors of  Accreta</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18253]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>ART. </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18254]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Age.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18255]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Surgical trauma.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18256]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>E &amp; C.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18257]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Endometritis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18258]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>C – Section.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18259]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>1 – 3%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18260]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>2 – 11%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18261]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>3 – 40%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18262]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>4 – 61%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18263]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>5 – 67%.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18264]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Uterine pathology.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18265]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>Fibroids.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18266]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>Adenomyosis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18267]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 10pt''>BI corporeal uteri.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18268]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Maternal Age.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18269]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Short interval from C/ Section.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18270]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>Pre</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>labor C/ Section.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18271]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18272]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18273]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18274]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18275]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>Management of placenta previa and PAS</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18276]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><strong>Localization of placenta</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18277]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Low lying &lt;20mm from OS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18278]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Previa coving the OS</span></p>
