INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-029-0', 't-mm-09-029', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-029" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19207]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>16. </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>ANC OF SINGLETON PREGNANCY CONCEIVED USING ART:</strong></span></p>
<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;margin-left:0pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:179.8pt;"><col style="width:179.85pt;"><col style="width:179.85pt;"></colgroup><tbody><tr><td style="white-space:pre-wrap;width:179.8pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">Condition</p></td><td style="white-space:pre-wrap;width:179.85pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">Incidence</p></td><td style="white-space:pre-wrap;width:179.85pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">Recommendations</p></td></tr><tr><td style="white-space:pre-wrap;width:179.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><figure class="mm-figure" data-mm-figure-id="c99399d5cac01224a239a56e" data-mm-topic-id="t-mm-09-029"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure c99399d5cac01224a239a56e" viewbox="428625 123825 257175 361950" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="851c48a739f7984a33545c140d28e472b2f40632a09539a19569a1d8ab90bdb6"><defs><marker id="arrow-end-d0329aa99f68b16d39f4" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#4472C4"></path></marker></defs><g data-mm-object-id="d0329aa99f68b16d39f4" transform="translate(556895 168275)"><g transform="translate(0 0)"><path d="M 0 0 L 6350 203200" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-d0329aa99f68b16d39f4)"></path></g></g></svg></figure>OHSS</p><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">Risk of VTE</p><p style="margin:0;margin-bottom:8pt;">PIH</p><p style="margin:0;margin-bottom:8pt;">PTL</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Mild – 33%.</p><p style="margin:0;margin-bottom:8pt;">Mod – severe 3.1 – 8%.</p><p style="margin:0;margin-bottom:8pt;">Risk of VTE = 0.7 – 10%.</p><p style="margin:0;margin-bottom:8pt;">Upper body &amp; arterial system after resolution of OHSS.</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Establish evidence based local protocols.</p><p style="margin:0;margin-bottom:8pt;">Admission to nominated centers.</p><p style="margin:0;margin-bottom:8pt;">Reporting to HEFA severe &amp; critical.</p></td></tr><tr><td style="white-space:pre-wrap;width:179.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Miscarriages </p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">15 – 20%</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><ul style="list-style-type:none;margin:0 0 0 36pt;padding:0;text-indent:-18pt;"><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Manage as spontaneous miscarriage.</li><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Women should have access to specialist counselor before, during &amp; after ART.</li></ul><p style="margin:0;padding-left:36pt;margin-bottom:8pt;"></p></td></tr><tr><td style="white-space:pre-wrap;width:179.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Ectopic </p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">1.4%</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><ul style="list-style-type:none;margin:0 0 0 36pt;padding:0;text-indent:-18pt;"><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Same as miscarriage</li><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Careful inspection of adnexa on USG.</li><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Be mindful of heterotopic pregnancy</li></ul><p style="margin:0;padding-left:36pt;margin-bottom:8pt;"></p></td></tr><tr><td style="white-space:pre-wrap;width:179.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">PIH – more if </p><p style="margin:0;margin-bottom:8pt;">Age &gt; 35 years</p><p style="margin:0;margin-bottom:8pt;">BMI &gt; 30.</p><p style="margin:0;margin-bottom:8pt;">PCOS</p><p style="margin:0;margin-bottom:8pt;">Multiple pregnancy</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">2% more than natural conception</p><p style="margin:0;margin-bottom:8pt;">More in egg donation.</p><p style="margin:0;margin-bottom:8pt;">Sperm donation or</p><p style="margin:0;margin-bottom:8pt;">Embryo donation.</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><ul style="list-style-type:none;margin:0 0 0 36pt;padding:0;text-indent:-18pt;"><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Risk assessment @ booking.</li><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Aspirin 75mg from 12 weeks if risk Factor positive (not on basis of ART).</li></ul></td></tr><tr><td style="white-space:pre-wrap;width:179.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">GDM – more in PCOS</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><figure class="mm-figure" data-mm-figure-id="c3dcecb0594359193d01697a" data-mm-topic-id="t-mm-09-029"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure c3dcecb0594359193d01697a" viewbox="600075 -76200 228600 285750" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="58b9f44c10ae1c14757ef15c87e10499013e179b9d41058ec7255d07aa0588c5"><defs><marker id="arrow-end-1976406e11e3d9b7dd1e" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#000000"></path></marker></defs><g data-mm-object-id="1976406e11e3d9b7dd1e" transform="translate(724535 8255)"><g transform="translate(0 0) translate(0 69850) rotate(0) scale(1 -1) translate(0 -69850)"><path d="M 0 0 L 1 139700" fill="none" fill-opacity="0" stroke="#000000" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-1976406e11e3d9b7dd1e)"></path></g></g></svg></figure>1% </p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">ART not an indication of OGTT</p></td></tr><tr><td style="white-space:pre-wrap;width:179.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">VTE</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><figure class="mm-figure" data-mm-figure-id="6863a43eb8f5645268229638" data-mm-topic-id="t-mm-09-029"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 6863a43eb8f5645268229638" viewbox="1181100 28575 209550 152400" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="37ed4fe6bb0f849bcdba8e7ddc2ad1ab2c1fa3704c929176f889149d41e4d296"><g data-mm-object-id="f8fdb45612078b5a91d0" transform="translate(1207135 59690)"><g transform="translate(0 0)"><path d="M 0 95250 L 63500 0 L 127000 95250 Z" fill="#4472C4" fill-opacity="1" stroke="#223962" stroke-opacity="1" stroke-width="12700"></path></g></g></svg></figure>Highest in 1st </p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><ul style="list-style-type:none;margin:0 0 0 36pt;padding:0;text-indent:-18pt;"><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Alone ART is not an indication for prophylaxis.</li><li data-source-marker-codepoints="U+F0B7" data-source-marker-font="Symbol"><span class="list-prefix" style="display:inline-flex;width:18pt;"><span class="list-marker">•</span><span class="list-tab" aria-hidden="true" data-list-suffix="tab" style="flex:1 1 auto;min-width:0;"></span></span>Risk assessment.</li></ul><p style="margin:0;padding-left:36pt;margin-bottom:8pt;"></p></td></tr><tr><td style="white-space:pre-wrap;width:179.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Subclinical hypothyroidism</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><figure class="mm-figure" data-mm-figure-id="d2d123273ef1b38ba6a6dd69" data-mm-topic-id="t-mm-09-029"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure d2d123273ef1b38ba6a6dd69" viewbox="2085975 -9525 238125 295275" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="0b856104dabeea2d87f15e0cbc8201b1ec3ee39108bda4112d3b7d62de911965"><defs><marker id="arrow-end-19cabbb2ebc35ab31df0" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#000000"></path></marker></defs><g data-mm-object-id="19cabbb2ebc35ab31df0" transform="translate(2213610 43180)"><g transform="translate(0 0)"><path d="M 0 0 L 1 132080" fill="none" fill-opacity="0" stroke="#000000" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-19cabbb2ebc35ab31df0)"></path></g></g></svg></figure>Treatment of subclinical hypo    es risk of miscarriage in ART pregnancies (limited evidence).</p><p style="margin:0;margin-bottom:8pt;"></p></td></tr><tr><td colspan="3" style="white-space:pre-wrap;width:539.5pt;background-color:#B4C6E7;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;">Fetal complications</p></td></tr><tr><td style="white-space:pre-wrap;width:179.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Structural Anomalies</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><figure class="mm-figure" data-mm-figure-id="47229a9f5a987b66d8c5a38d" data-mm-topic-id="t-mm-09-029"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 47229a9f5a987b66d8c5a38d" viewbox="933450 -76200 228600 295275" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="9f608d3ac0eaeb0b5f70c6fc4369d9f4fa5912a596de09e54a3e91fb01f8ca1d"><defs><marker id="arrow-end-0f62d3f94961b5182f08" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#000000"></path></marker></defs><g data-mm-object-id="0f62d3f94961b5182f08" transform="translate(1054735 13335)"><g transform="translate(0 0) translate(0 63500) rotate(0) scale(1 -1) translate(0 -63500)"><path d="M 0 0 L 1 127000" fill="none" fill-opacity="0" stroke="#000000" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-0f62d3f94961b5182f08)"></path></g></g></svg></figure>30 – 40%     risk</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p></td></tr><tr><td style="white-space:pre-wrap;width:179.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Oligospermia =&gt; Autosomal translocation or inversion 4.6 – 13.7%</p><p style="margin:0;margin-bottom:8pt;">Microdeletion = 5 – 15%.</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Absolute risk</p><p style="margin:0;margin-bottom:8pt;">More in ICSI 6.5 – 7%</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p><p style="margin:0;margin-bottom:8pt;">No additional surveillance.</p></td></tr><tr><td style="white-space:pre-wrap;width:179.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">IUGR:</p><p style="margin:0;margin-bottom:8pt;">ART minor risk Factor for SGA</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">No additional surveillance.</p></td></tr><tr><td style="white-space:pre-wrap;width:179.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">S. B</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">2.4-fold</p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">Delivery @ Term IOL or C/Section</p></td></tr><tr><td style="white-space:pre-wrap;width:179.8pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;">PTL </p></td><td style="white-space:pre-wrap;width:179.85pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-botto