INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-09-033-0', 't-mm-09-033', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-033" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19432]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>20. </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>ANTENATAL CORTICOSTEROID:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19433]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Benefits:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19434]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>If given </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>within</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> 7 </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>days</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> of preterm birth</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19435]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>  Perinatal and neonatal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>death</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19436]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>RDS</span><span class="mm-tab" aria-hidden="true">	</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19437]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>If given in planned c section between 37-38+6 weeks </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19438]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>NICU admission for RDS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19439]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Uncertainty</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in RDS</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> reduction</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19440]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Uncertainty in TTN reduction</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>    </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19441]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Uncertainty</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in overall NNU admission</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19442]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19443]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>      </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19444]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19445]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Risks:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19446]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypoglycemia to neonate</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19447]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Potential developmental delay</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19448]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Steroid talk:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19449]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Discussion before offering or considering steroid.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19450]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Should involve women in discussion</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19451]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Informed decision of women should be there</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19452]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>It is Gestation related</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19453]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Discussion should be based on following points</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19454]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19455]"><span class="mm-run" style=''color: ##44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>Table </em></span><span class="mm-run" style=''color: ##44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>42</em></span><span class="mm-run" style=''color: ##44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>. </em></span><span class="mm-run" style=''color: ##44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>ANTENATAL CORTICOSTEROID</em></span></p>
