INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-10-002-0', 't-mm-10-002', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-002" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19769]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>TYPES OF BIRTH SETTING</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19770]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>1.</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Home birth:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19771]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>(Multiparous low risk)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19772]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>2.</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Free standing midwifery</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19773]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>(low risk primi</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>gravida</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> and multi</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>gravida</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19774]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>3.</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Alongside midwifery </strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19775]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>(low risk primi</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>gravida</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> and multi</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>gravida</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19776]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>4.</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Consultant led unit</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19777]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''><u>(high risk pregnancies)</u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19778]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Low risk multi gravida:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19779]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Home birth</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. Low risk</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> of</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> intervention</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19780]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Midwifery units</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2. Outcome is same</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3. Familiar environment and </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>     midwife.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4. Need of transfer of care.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19781]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Consultant led </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-    Ed intervention.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- Outcome is same.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19782]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Low risk Primigravida:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19783]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Home Birth – </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>   </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>chances of complication to baby</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19784]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Midwifery – low intervention</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19785]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>       -  Outcome same.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19786]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Consultant let – more interventions</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19787]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Less complications</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19788]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Outcome is same</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19789]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19790]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Transfer of care to obstetric Unit:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19791]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Indications/ Reasons:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19792]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Delay during 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or 2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>nd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> stage.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19793]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Abnormal fetal heart rate.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19794]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Request of regional analgesia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19795]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Meconium staining</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19796]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Retained placenta</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19797]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Repair of perineal trauma</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19798]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Postpartum neonatal concerns.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19799]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Care during transfer of care:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19800]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Talk to women and her birth companion and address their concerns.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19801]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Midwife should contact ambulance and coordinating midwife in obstetric unit. The coordinating midwife should then alert relevant healthcare professionals (obstetric, anesthetic, neonatal)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19802]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Transfer without any delay. Categories the transfer according to urgency.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19803]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Category 1 – life threatening emergency</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19804]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Category 2 – urgent for example pain relief.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19805]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Before transfer dress her up, make her comfortable and covered.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19806]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Maintain good communication and companionship.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19807]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Explain all procedure and persons involved.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19808]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Accompany the woman during transfer especially the midwife who was involved in her care.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19809]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Monitoring during transfer – fetal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>monitoring by intermitting </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>auscu</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ltation</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19810]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Factors affecting place of Birth:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19811]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Maternal medical conditions.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19812]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Obstetric problems in current pregnancy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19813]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Past obstetric history</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19814]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Current intrapartum problems like</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19815]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Temp &gt; 37.5 on 2 reading or 38</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>C single reading.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19816]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>B.P</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19817]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19818]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19819]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19820]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>160/110 – single reading.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19821]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>140/90 – 2 readings.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[19822]"><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>140/90 </span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>along with</span><span class="mm-run" style=''color: ##2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> 2 + proteinuria.</span></p>
