INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-10-011-0', 't-mm-10-011', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-011" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20525]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>INTRAPARTUM CARE OF WOMAN WITH EXISTING MEDICAL CONDITIONS AND OBSTETRIC COMPLICATIONS</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20526]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>All women with medical disorders should have personalized intrapartum care plan along with contingency plan.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20527]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Care plan should be formulated in MDT, in discussion with women and her companion.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20528]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>MDT can be consisting of </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20529]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Midwife</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20530]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>An obstetrician</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20531]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>An obstetric anesthetist</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20532]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>An obstetric physician</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20533]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A clinical expert in medical condition</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20534]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A Specialty surgeon</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20535]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>7. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>A critical care specialist</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20536]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>8. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Neonatologist</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20537]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>9. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>The women’s GP</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20538]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>10. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Allied health professionals.</span></p>', 0);

DELETE FROM content_blocks WHERE topic_id = 't-mm-10-012';
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-10-012-0', 't-mm-10-012', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-012" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20539]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 12pt''>3.1. </span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 12pt''>HEART DISEASE</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20540]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Newly diagnosed heart disease in labor =&gt; urgent MDT discussion</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20541]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk identification according to modified WHO classification of maternal cardiovascular risk.</span></p>', 0);
INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-10-012-1', 't-mm-10-012', 'document_html', '<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;table-layout:fixed;margin-left:14.7pt;border-top:6pt solid #DAEBEC;border-right:6pt solid #DAEBEC;border-bottom:6pt solid #DAEBEC;border-left:6pt solid #DAEBEC;"><colgroup><col style="width:8.15pt;"><col style="width:78.85pt;"><col style="width:78pt;"><col style="width:72pt;"><col style="width:84pt;"><col style="width:91.2pt;"><col style="width:78.9pt;"><col style="width:4.5pt;"><col style="width:6.15pt;"></colgroup><tbody><tr data-mm-row-height-twips="424" data-mm-row-height-rule="auto"><td colspan="9" style="white-space:pre-wrap;width:501.75pt;background-color:#DAEBEC;border-top:none;border-right:none;border-bottom:1.5pt solid #D7143F;border-left:6pt solid #DAEBEC;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:3pt;margin-top:4.55pt;margin-bottom:0pt;">Table Modified World Health Organization classification of maternal cardiovascular risk</p></td></tr><tr data-mm-row-height-twips="94" data-mm-row-height-rule="auto"><td colspan="8" style="white-space:pre-wrap;width:495.6pt;border-top:1.5pt solid #D7143F;border-right:none;border-bottom:0.25pt solid #000000;border-left:6pt solid #DAEBEC;padding-right:0pt;padding-left:0pt;"><p style="margin:0;margin-bottom:0pt;"></p></td><td rowspan="22" style="white-space:pre-wrap;width:6.15pt;background-color:#DAEBEC;border-top:none;border-right:none;border-bottom:none;border-left:none;padding-right:0pt;padding-left:0pt;"><p style="margin:0;margin-bottom:0pt;"></p></td></tr><tr data-mm-row-height-twips="327" data-mm-row-height-rule="auto"><td rowspan="41" style="white-space:pre-wrap;width:8.15pt;background-color:#DAEBEC;border-top:none;border-right:0.5pt solid #000000;border-bottom:1.5pt solid #D7143F;border-left:6pt solid #DAEBEC;padding-right:0pt;padding-left:0pt;"><p style="margin:0;margin-bottom:0pt;"></p></td><td style="white-space:pre-wrap;width:78.85pt;background-color:#9CC1E1;border-top:0.25pt solid #000000;border-right:0.75pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;margin-bottom:0pt;"></p></td><td style="white-space:pre-wrap;width:78pt;background-color:#9CC1E1;border-top:0.25pt solid #000000;border-right:0.75pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:5.85pt;margin-top:4.7pt;margin-bottom:0pt;">mWHO I</p></td><td style="white-space:pre-wrap;width:72pt;background-color:#9CC1E1;border-top:0.25pt solid #000000;border-right:0.75pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:5.85pt;margin-top:4.7pt;margin-bottom:0pt;">mWHO II</p></td><td style="white-space:pre-wrap;width:84pt;background-color:#9CC1E1;border-top:0.25pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:5.85pt;margin-top:4.7pt;margin-bottom:0pt;">mWHO II–III</p></td><td style="white-space:pre-wrap;width:91.2pt;background-color:#9CC1E1;border-top:0.25pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:5.95pt;margin-top:4.7pt;margin-bottom:0pt;">mWHO III</p></td><td style="white-space:pre-wrap;width:78.9pt;background-color:#9CC1E1;border-top:0.25pt solid #000000;border-right:0.25pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:6pt;margin-top:4.7pt;margin-bottom:0pt;">mWHO IV</p></td><td rowspan="21" style="white-space:pre-wrap;width:4.5pt;background-color:#DAEBEC;border-top:none;border-right:none;border-bottom:none;border-left:0.25pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;margin-bottom:0pt;"></p></td></tr><tr data-mm-row-height-twips="260" data-mm-row-height-rule="auto"><td style="white-space:pre-wrap;width:78.85pt;border-top:0.5pt solid #000000;border-right:0.75pt solid #000000;border-bottom:none;border-left:0.5pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:8.8pt;margin-top:4.05pt;margin-bottom:0pt;">Diagnosis (if other-</p></td><td style="white-space:pre-wrap;width:78pt;border-top:0.5pt solid #000000;border-right:0.75pt solid #000000;border-bottom:none;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:5.85pt;margin-top:4.05pt;margin-bottom:0pt;">Small or mild</p></td><td style="white-space:pre-wrap;width:72pt;border-top:0.5pt solid #000000;border-right:0.75pt solid #000000;border-bottom:none;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:5.85pt;margin-top:4.05pt;margin-bottom:0pt;">Unoperated atrial or</p></td><td style="white-space:pre-wrap;width:84pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:none;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:5.85pt;margin-top:4.05pt;margin-bottom:0pt;">Mild left ventricular impairment</p></td><td style="white-space:pre-wrap;width:91.2pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:none;border-left:0.5pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:5.95pt;margin-top:4.05pt;margin-bottom:0pt;">Moderate left ventricular</p></td><td style="white-space:pre-wrap;width:78.9pt;border-top:0.5pt solid #000000;border-right:0.25pt solid #000000;border-bottom:none;border-left:0.5pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:6pt;margin-top:4.05pt;margin-bottom:0pt;">Pulmonary arterial</p></td></tr><tr data-mm-row-height-twips="189" data-mm-row-height-rule="auto"><td style="white-space:pre-wrap;width:78.85pt;border-top:none;border-right:0.75pt solid #000000;border-bottom:none;border-left:0.5pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:8.8pt;margin-top:0.5pt;margin-bottom:0pt;">wise well and</p></td><td style="white-space:pre-wrap;width:78pt;border-top:none;border-right:0.75pt solid #000000;border-bottom:none;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:6.15pt;margin-top:0.5pt;margin-bottom:0pt;">– pulmonary stenosis</p></td><td style="white-space:pre-wrap;width:72pt;border-top:none;border-right:0.75pt solid #000000;border-bottom:none;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:5.85pt;margin-top:0.5pt;margin-bottom:0pt;">ventricular septal</p></td><td style="white-space:pre-wrap;width:84pt;border-top:none;border-right:0.5pt solid #000000;border-bottom:none;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;margin-top:0.5pt;margin-bottom:0pt;"> (EF &gt;45%)</p></td><td style="white-space:pre-wrap;width:91.2pt;border-top:none;border-right:0.5pt solid #000000;border-bottom:none;border-left:0.5pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:5.95pt;margin-top:0.5pt;margin-bottom:0pt;">impairment (EF 30–45%)</p></td><td style="white-space:pre-wrap;width:78.9pt;border-top:none;border-right:0.25pt solid #000000;border-bottom:none;border-left:0.5pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;padding-left:6pt;margin-top:0.5pt;margin-bottom:0pt;">hypertension</p></td></tr><tr data-mm-row-height-twips="839" data-mm-row-height-rule="auto"><td style="white-space:pre-wrap;width:78.85pt;bord