INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-10-022-0', 't-mm-10-022', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-022" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20989]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>INTRA – PARTUM HAEMORRHAGE:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20990]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Causes:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20991]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Placenta previa</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20992]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Placental abruption</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20993]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vasa previa</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20994]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Uterine rupture</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20995]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Most of the times no cause</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20996]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>History:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20997]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Amount of blood loss</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20998]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pain</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20999]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Previous surgery</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21000]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Any other concern</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21001]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Previous scan to check localization of placenta</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21002]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Examination:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21003]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Blood loss:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21004]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>characteristics of blood</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21005]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Colour</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21006]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Presence of clots</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21007]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Amniotic fluid</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21008]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Physical examination:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21009]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vital signs</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21010]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Abdominal palpation</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21011]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Speculum examination</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21012]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vaginal examination if previa has been excluded</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21013]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FH</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>R</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21014]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21015]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Management</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21016]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Start CTG</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21017]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Blood group and CBC</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21018]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21019]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>MDT </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Senior obstetrician</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Senior obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tetric</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> anesthetist</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Senior midwife</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Labour ward coordinator</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Just a show</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Not a show</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21020]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21021]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Manage as normal labour</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21022]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21023]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21024]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Unstable:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Escalate obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tetric</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> haemorrhage protocol.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Immediate resuscitation</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>I/V fluids</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CBC + Cross match</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Clotting studies</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Use of amniotomy or oxytocin</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Expedite birth transfer to obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tetric</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> unit if not already in</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Vitally stable:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>I/V access</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FHR monitoring by CTG</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Maternal monitoring</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21025]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21026]"> </p>
