INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-10-033-0', 't-mm-10-033', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-033" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21673]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>9.</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>VBAC</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21674]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><strong>Success of VBAC after 1 C/S</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21675]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>1. VBAC </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>After</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong> C/S due to malpresentation </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>=&gt; 84% </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>successful</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21676]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>2. Fetal distress &gt; 73%</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21677]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>3. Dystocia &gt; 64%</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21678]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>4. 70% after 1 LSCS</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21679]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>5.90% after </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>at least</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong> 1 SVD</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21680]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>6. plan of birth @ 3</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>6 weeks</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong> should be made</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>.</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21681]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>7. Plan of labour before decided </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>elective </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>CS should be written.</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21682]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>8. 10% scheduled </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>elective </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>CS go into labour before 39 weeks’ </strong></u></span></p>
