INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-10-034-0', 't-mm-10-034', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-034" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21801]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>10. </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>SHOULDER DYSTOCIA (SD)</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21802]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>incidence 0.58</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – 0.70% </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21803]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>48% in infants weighing &lt; 4kg</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21804]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Prediction </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>– 16% by conventional methods</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21805]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Brachial Plexus Injury:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21806]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>BPI</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – is commonest cause of litigation due to SD and 3</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>rd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> common cause related to obstetrics.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21807]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Leads to 10% permanent neurological damage.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21808]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>Risk factors</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21809]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Pre labour</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21810]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Previous shoulder dystocia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21811]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Macrosomia &gt; 4.5kg</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21812]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>DM (</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2 to 4-fold</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21813]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>BMI &gt; 30</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21814]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IOL</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21815]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>I</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>ntrapartum</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21816]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Prolong 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> stage </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21817]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2. S</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>econdary arrest</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21818]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Prolong 2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>nd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> stage</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21819]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Oxytocin augmentation</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21820]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Assisted vaginal delivery.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21821]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>Diagnosis:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21822]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Difficulty with delivery of face and chin</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21823]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Turtle neck sign </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21824]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Failure of restitution</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21825]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Failure of shoulder to descend</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21826]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Axial traction can be used</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21827]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Lateral and any other avoided =&gt; nerve avulsion injury</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21828]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21829]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>Prevention</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21830]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IOL</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21831]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Don’t prevent in non-diabetic macrosomia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21832]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Prevent SD in diabetic macrosomia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21833]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>E</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lective</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> C/S consider in DM + EFW &gt; 4.5kg</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21834]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Post-natal Management of women/ New Born:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21835]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Maternal risks:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21836]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PPH 11%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21837]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Perineal tear (3</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>rd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/4</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>th</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> degree) 38%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21838]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vaginal, cervical laceration</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21839]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bladder rupture</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21840]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Uterine rupture</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21841]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Symphysial separation</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21842]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sacra iliac joint dislocation</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21843]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Lateral femoral cutaneous neuropathy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21844]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Fetal risks:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21845]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. BPI – 2.3 – 16%, </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21846]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>46%</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> of BPI</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> due to </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>substandard </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>care.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21847]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>10% permanent injury to nerve, 4% during C/S and</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 12% after simple C/S</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21848]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Always document the anterior shoulder as posterior shoulder is never because of health care </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>professionals’</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> undue </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>traction,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>post shoulder is always affected by maternal effort</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21849]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2. Humerus facture.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21850]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3. Clavicle fracture.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21851]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21852]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 14pt''><u><strong>Recurrence:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21853]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>10 times higher = 1 – 25%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21854]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Either c/s or vaginal birth – joint decision between women and her carer</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21855]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21856]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21857]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>   </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Call for help:</span></p>
