INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-10-037-0', 't-mm-10-037', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-037" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22103]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>1</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>3</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>. </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>INDUCTION OF </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>LABOUR:</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong> </strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>IOL</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22104]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1/5 pregnancies need IOL</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22105]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2/3 give birth without intervention</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22106]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>15</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>% need </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>AVB</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22107]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>22%</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> end up in C</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/S</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22108]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Most women go into labo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>u</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>r by 42 weeks</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22109]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>@ 38 weeks all women should be offered information regarding</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22110]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk of pregnancies that last longer than 42 weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22111]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Expectant management</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22112]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Membranes stripping</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22113]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Method </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22114]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>benefits of spontaneous labour</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22115]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Uncomfortable, pain</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22116]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Possible bleeding</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22117]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IOL between 41 – 42 weeks</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22118]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 13pt''><strong>Information giving before IOL:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22119]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Reason</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22120]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>When, where, how </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22121]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Support, pain relief</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22122]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Alternative to IOL</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22123]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk/ Benefits of IOL</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22124]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>what if IOL fails</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22125]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>7. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>prolong pregnancy IOL between 41 – 42 weeks exact timing according to patient’s wishes patient who decline =&gt; after 42 weeks</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22126]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CTG + Amniotic Fluid =&gt; twice/ week</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22127]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PPROM</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22128]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Before 37 weeks expectant management, to prolong till 37 weeks. In case of fetomaternal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>indications</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> offer IOL</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22129]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PROM =&gt; 24 hours after ROM</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> offer IOL</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22130]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Previous CS – PG E</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/ expectant according to women wishes, explain risk of rupture and em</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ergency</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> CS</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22131]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Maternal request @ or after 40 weeks =&gt; under special conditions</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22132]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Breech – Not recommended</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22133]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Severe IUGR + compromise NR</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22134]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>History of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>precipitated</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> labor – not routinely offered</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22135]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IUD</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22136]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Patient physically </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Offer a choice of </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22137]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>w</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ell</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>expectant/ IOL</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> by</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22138]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No infection</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mifepristone,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> FPG E</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22139]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No bleeding </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>or </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>misoprostol</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22140]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22141]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Unwell</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22142]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>+</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> bleeding</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>+</u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> infection</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IOL</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22143]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ruptured management</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22144]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22145]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22146]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IUD + previous </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22147]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>CS =&gt; risk of rupture, reduce dose of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''>MISO</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22148]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fetal macrosomia =&gt; Discuss</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22149]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Methods:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22150]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sweeping of Membranes = Adjunct to IOL</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22151]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>primigravida</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> = 40 – 41weeks</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22152]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Multi</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>gravida</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> = 41 weeks </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22153]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>additional </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>sweeping</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> can be done if patient don’t go into labor.</span></p>
