INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-11-010-0', 't-mm-11-010', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-11-010" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23311]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>DEPRESSION</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23312]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>During pregnancy 12%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23313]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3 months PP = 13%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23314]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1-year after delivery = 15 – 20%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23315]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Past history and FH    es risk 42%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23316]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bipolar depression – risk of psychosis.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23317]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Diagnostic key words:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23318]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Lack of interest in friends, life, baby</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23319]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Persistent sadness low mood</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23320]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Don’t improve but worse with time</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23321]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fatigue or low energy.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23322]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Worthlessness and hopelessness</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23323]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23324]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Associated symptoms:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23325]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sleep disturbance </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23326]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Indecisiveness</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23327]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Poor or     ed appetite</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23328]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Suicidal thoughts </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23329]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Agitation or slowing of movements</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23330]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Guilt or </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>self-blame</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23331]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Impaired social or occupational activities</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23332]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Poor </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>concentration</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23333]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Low </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>self-confidence</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23334]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Post – partum depression:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23335]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Onset: 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 2weeks after birth</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23336]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2 peak</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> presentations</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23337]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>@</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 2 – 4weeks</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pp</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23338]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>nd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>@</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 10 – 14weeks</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pp</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23339]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FH + Personal History of depression = 42%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23340]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Postnatal depression</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23341]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Greatest at 6 – 8weeks.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23342]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Only personal depression = 15% chance of PP depression.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23343]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk of recurrence in future pregnancies 1:2 – 1:3</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23344]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23345]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Depression Screening:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23346]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Feeling down, hopeless, depressed over month</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23347]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Lack of interest over past month</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23348]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23349]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23350]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Or 2 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>positives</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23351]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23352]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Full assessment by</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23353]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Ed</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>i</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>nberg Postnatal Scale</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23354]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Or </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23355]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Patient health Questionnaire</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23356]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><strong>Over the last 2 weeks, how often have you been bothered by any of the following problems:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23357]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Little interest or pleasure in doing things?</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23358]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Feeling down, depressed, or hopeless?</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23359]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Trouble falling or staying asleep, or sleeping too much?</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23360]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Feeling tired or having little energy?</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23361]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Poor appetite or overeating?</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23362]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Feeling bad about yourself – or that you are a failure or have let yourself or your family down?</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23363]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Trouble concentrating on things, such as reading the newspaper or watching television?</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23364]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Moving or speaking so slowly that other people could have noticed?</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23365]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Or the opposite – being so </span><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>uneasy</span><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''> or restless that you have been moving around a lot more than usual?</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23366]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Thoughts that you would be better off dead, or thoughts of hurting yourself in some way?</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23367]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Rating:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23368]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Not at all:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 0</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23369]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Several days:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 1</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23370]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>More than half the days:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 2</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23371]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Nearly every day:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 3</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23372]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Depression severity</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23373]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>0–4:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> none</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23374]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>5–9:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> mild</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23375]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>10–14:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> moderate</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23376]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>15–19:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> moderately severe</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23377]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>20–27:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> severe</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23378]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Fetomaternal Consequences of Depression:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23379]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Mother:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23380]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Relapse</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23381]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Poor nutrition</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23382]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Suicide</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23383]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Drug abuse</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23384]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Postnatal depression</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23385]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Baby:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23386]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Abortion</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23387]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pre term birth</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23388]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>LBW</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23389]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Low APGAR</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23390]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>NICU admission</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23391]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Breast feeding problems</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23392]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Management:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23393]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Women not taking any treatment or newly diagnose</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23394]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>1. </strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Mild – Moderate:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23395]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23396]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Refer to</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23397]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Local psychology services</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23398]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Primary care mental health</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23399]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23400]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Low intensity CBT</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23401]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>9 – 12weeks therapy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23402]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6 – 8 min sessions f</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ace to face or telephonic</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23403]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>30 – 60min session</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23404]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Every week or fortnightly</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23405]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23406]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>2. </strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Moderate</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>-</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> Severe:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23407]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>High intensity CBT </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23408]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pharmacological treatment</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23409]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>SSRI</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23410]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>SNRI</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23411]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>TCA</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23412]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>In case she declines CBT, or CBT is ineffective.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23413]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Comb</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ination</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> of CBT and medications if alone CBT or medications are not effective.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23414]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Severe Depression:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23415]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Catatonic features, psychotic features</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23416]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Switch antidepressants if already taking or</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23417]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Augmentation treatment with antipsychotic or mood stabilizers.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23418]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ECT – in severe or </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>life-threatening</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> conditions.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23419]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>3. </strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Mild depression + Past History of Severe Depression:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23420]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>TCA</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23421]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>SSRI</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23422]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>SNRI</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23423]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Women taking medications before pregnancy</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23424]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23425]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Mild – moderate</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Moderate</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Severe </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23426]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23427]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Stop gradually</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>switch </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>     Don’t stop</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23428]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>G</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>radually</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>     -</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Continuous</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23429]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>and switch to</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>     or </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23430]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Facilitated </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- CBT or</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- change to </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23431]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Self-help</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- Other </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>medication </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23432]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>M</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>edication</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>with least</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23433]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>is effective </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>adverse </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>effects</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23434]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>with </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>or</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23435]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lower side </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Combo </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>CBT</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23436]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>effect</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>(high </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>intensity</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23437]"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>and </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>medication</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>or</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>Switch </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>to </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>high</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>intensity CBC.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23438]"> </p>', 0);

