INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-11-014-0', 't-mm-11-014', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-11-014" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23713]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>6.8. </span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>EATING DISORDERS:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23714]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6 – fold     in perinatal mortality</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23715]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Association with psychiatric disorder</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23716]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Relapses in pregnancy</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23717]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fetal growth abnormalities</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23718]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Feeding problems </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23719]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>anorexia has highest mortality among all psychiatric disorders.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23720]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Management:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23721]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Discuss healthy eating and its benefits</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23722]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Offer support regarding nutrition</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23723]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Psychological intervention</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23724]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Growth scans</span></p>', 0);

