INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-11-016-0', 't-mm-11-016', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-11-016" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23733]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>DRUG MISUSE:</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23734]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Alcohol:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23735]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If suspected use AUDIT test </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23736]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>AUDIT</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> test</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>:</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> </strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Is a </strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>10-item</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> screening tool developed by WHO to assess alcohol consumption, drinking behaviors and alcohol related problems.</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23737]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Offer detoxification</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23738]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Manage in collaboration with mental health and substance misuse services</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23739]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anomaly scan</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23740]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Identify risk of accidental overdose</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23741]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Offer treatment and support after child birth</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23742]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Neonatal assessment to rule out congenital</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>abnormalities and neonatal adaption syndrome.</span></p>', 0);

