INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-11-018-0', 't-mm-11-018', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-11-018" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23771]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>MATERNAL MORTALITY</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23772]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>WHO</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> definitions</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23773]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Maternal Death </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>during </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>pregnancy and within </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>4</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>2 days of Birth</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23774]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23775]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pre – existing diseases</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Developed during pregnancy </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>b</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ut not the result of direct obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tetric</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> cause</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Aggregated by physiological effect of pregnancy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Examples:</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cardiac:</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> most</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>common</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Epilepsy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Status asthmaticus</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>DKA</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Unrelated causes:</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Domestic </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>violence</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Road traffic</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>accidents</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>42 – days – 1year</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> after birth </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Either from direct or indirect causes</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Examples:</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Psychiatric illness</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Accidental overdose</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cardiac disease that was aggravated by pregnancy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Direct </strong></em></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>In Direct</strong></em></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>late</strong></em></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>coincidental </strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em>death due to</em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em> </em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Complication</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> of</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23776]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> </strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pregnancy state</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23777]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>labour </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23778]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>puerperium</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23779]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pregnancy Intervention</span></p>
