INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-12-001-0', 't-mm-12-001', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-12-001" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23992]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>2. INDUCTION INTERVIEW</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong> /APPRAISAL</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23993]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Meeting with educational supervisor within 2 wks of induction</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23994]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Review e log and current competencies</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23995]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Set achieveable goals</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23996]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Add educational goals</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23997]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Record meetingon induction/appraisal form</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23998]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>APPRAISAL</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23999]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>is done after </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a duration like one year after induction to assess that goals are achieved or not</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24000]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Purpose is to test competences</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24001]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>once per year , continuous process</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24002]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>informal meeting between apraiser and apraisee</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> on a mutually agreed time</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24003]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>both open and closed questions</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24004]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>apraisee should submit development plan 7-14 days before meeting</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24005]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>purpose is to ensure safe practise for licence and ARCP</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24006]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>apraiser is a good negotiator</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and listener</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24007]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>time distribution is 70/30</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24008]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>documented and record is kept</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24009]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>confidential but not legally protected</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24010]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24011]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24012]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24013]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24014]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24015]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24016]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24017]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24018]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24019]"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24020]"> </p>
