INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-12-005-0', 't-mm-12-005', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-12-005" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24166]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Times New Roman", sans-serif; font-size: 16pt''><strong>REFLECTION</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24167]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Learning from own experience</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24168]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><u><strong>Kolb’s</strong></u></span><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><u><strong> reflective practice</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24169]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>is a four-stage, continuous, experiential learning model where knowledge is created through transforming experience</span></p>
