INSERT INTO content_blocks (id, topic_id, type, content, `order`) VALUES ('cb-book-t-mm-13-005-0', 't-mm-13-005', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-13-005" hidden></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24441]"><span class="mm-run" style=''color: ##FFFFFF; font-family: "Times New Roman", sans-serif; font-size: 16pt''><strong>5</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Times New Roman", sans-serif; font-size: 16pt''><strong>. P</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Times New Roman", sans-serif; font-size: 16pt''><strong>ATIENT AND PUBLIC INVOLVEMENT</strong></span><span class="mm-run" style=''color: ##FFFFFF; font-family: "Times New Roman", sans-serif; font-size: 16pt''><strong> </strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24442]"><span class="mm-run" style=''color: ##222222; font-family: "Times New Roman", sans-serif; font-size: 12pt''>Pts and public can be engaged in a variety of ways</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24443]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Patient advisory and liaison services</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24444]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Quantitative pts surveys (questionnaires)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24445]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Qualitative pts surveys (depth interview, focus groups)</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24446]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Pts stories and diaries/observational studies</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24447]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Workshops and conferences</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24448]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Consultation with pt representative and group</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24449]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Pts forums, council and panels</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24450]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Pt representative committee and group</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24451]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><u><strong>Patient advisory liaison services </strong></u></span><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><u><strong>PALS</strong></u></span><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><u><strong> </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24452]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Where pts can enroll their complaints</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24453]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Whether they are annoyed, pleased or need inquiry</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24454]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><u>PALS statement</u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24455]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Happy: tell us</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24456]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Enquiry: let us help you</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24457]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Un</span><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>ha</span><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>ppy: let us resolve together</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24458]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><u><strong>Pts complaints</strong></u></span><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24459]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><u><strong>1.PALS:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24460]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Pts lodges their complaints at local level</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24461]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Majority of complaints are resoled locally</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24462]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>If not satisfied then refer to ombudsman</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24463]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><u><strong>2.</strong></u></span><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><u><strong>Ombudsman</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24464]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Parliamentary health services</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24465]"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Undertake independent investigations</span><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''> to complaints that has not been settled at the local level.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24466]"> </p>
